window.GITA=window.GITA||{};GITA.capitulos=GITA.capitulos||{};GITA.capitulos[5]={"numero": 5, "titulo": "El yoga de la renuncia a la acción", "versos": [{"n": 1, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "संन्यासं कर्मणां कृष्ण पुनर्योगं च शंससि ।", "यच्छ्रेय एतयोरेकं तन्मे ब्रूहि सुनिश्चितम् ॥१॥"], "iast": ["arjuna uvāca", "saṃnyāsaṃ karmaṇāṃ kṛṣṇa punar yogaṃ ca śaṃsasi", "yac chreya etayor ekaṃ tan me brūhi suniścitam"], "rojas": [], "t": "<span class=\"vt-parte\">Alabas, oh <a class=\"t\" href=\"glosario.html#krsna\" data-t=\"krsna\">Kṛṣṇa</a>, la <a class=\"t\" href=\"glosario.html#sannyasa\" data-t=\"sannyasa\">renuncia</a> a las <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a>, y luego el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>. De los dos, dime con certeza cuál es el mejor.</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "saṃnyāsam", "sa": "संन्यासम्", "gram": "ac. sg. m.", "es": "la renuncia", "ref": "sannyasa", "analisis": "sam-ni-√as (arrojar, depositar por completo)"}, {"iast": "karmaṇām", "sa": "कर्मणाम्", "gram": "gen. pl. n.", "es": "de las acciones", "ref": "karma"}, {"iast": "kṛṣṇa", "sa": "कृष्ण", "gram": "voc. sg. m.", "es": "oh Kṛṣṇa", "ref": "krsna"}, {"iast": "punaḥ", "sa": "पुनः", "gram": "ind.", "es": "y luego, otra vez"}, {"iast": "yogam", "sa": "योगम्", "gram": "ac. sg. m.", "es": "el yoga", "ref": "yoga"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "śaṃsasi", "sa": "शंससि", "gram": "2 sg. pres. act.", "es": "alabas", "analisis": "√śaṃs (alabar, recomendar)"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. rel.", "es": "lo que"}, {"iast": "śreyaḥ", "sa": "श्रेयः", "gram": "nom. sg. n.", "es": "mejor", "ref": "sreyas", "analisis": "comparativo de śrī: «más favorable»"}, {"iast": "etayoḥ", "sa": "एतयोः", "gram": "gen. du. pron.", "es": "de estos dos"}, {"iast": "ekam", "sa": "एकम्", "gram": "nom. sg. n.", "es": "uno solo"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "eso"}, {"iast": "me", "sa": "मे", "gram": "dat. sg. pron.", "es": "a mí"}, {"iast": "brūhi", "sa": "ब्रूहि", "gram": "2 sg. impv. act.", "es": "di", "analisis": "√brū (decir)"}, {"iast": "suniścitam", "sa": "सुनिश्चितम्", "gram": "ac. sg. n. ppp", "es": "con certeza", "analisis": "su (bien) + niś-√ci (decidir): «bien decidido»"}], "nota": "<p>Es la misma petición de <a class=\"vref\" href=\"capitulo-03.html#v2\" data-v=\"3.2\">3.2</a>: «dime con certeza una sola cosa». En el capítulo 4, Kṛṣṇa ha alabado el conocimiento que reduce a cenizas toda acción y a quien ha renunciado a las acciones por el yoga (<a class=\"vref\" href=\"capitulo-04.html#v37\" data-v=\"4.37\">4.37</a>, <a class=\"vref\" href=\"capitulo-04.html#v41\" data-v=\"4.41\">4.41</a>), y en el último verso le ha pedido que se establezca en el yoga y se levante (<a class=\"vref\" href=\"capitulo-04.html#v42\" data-v=\"4.42\">4.42</a>). A Arjuna le parecen dos consejos opuestos, y quiere uno solo (<em>ekam</em>).</p><p><em>Śreyas</em>, «lo mejor», es el mismo término de <a class=\"vref\" href=\"capitulo-02.html#v7\" data-v=\"2.7\">2.7</a> y <a class=\"vref\" href=\"capitulo-03.html#v2\" data-v=\"3.2\">3.2</a>: no sólo lo preferible, sino lo que conduce al bien.</p>", "interp": [{"titulo": "La pregunta que vuelve", "html": "<p>Arjuna repite, con otras palabras, la pregunta del comienzo del capítulo 3. Allí oponía el entendimiento a la acción; aquí, la renuncia al yoga. La Gītā avanza así, en espiral: cada respuesta de Kṛṣṇa deja un matiz que Arjuna vuelve a leer como alternativa, y cada vez Kṛṣṇa responde que no hay que elegir entre dos caminos, sino entender que llevan al mismo sitio (<a class=\"vref\" href=\"capitulo-05.html#v4\" data-v=\"5.4\">5.4</a>–<a class=\"vref\" href=\"capitulo-05.html#v5\" data-v=\"5.5\">5.5</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 2, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "संन्यासः कर्मयोगश्च निःश्रेयसकरावुभौ ।", "तयोस्तु कर्मसंन्यासात्कर्मयोगो विशिष्यते ॥२॥"], "iast": ["śrī-bhagavān uvāca", "saṃnyāsaḥ karma-yogaś ca niḥśreyasa-karāv ubhau", "tayos tu karma-saṃnyāsāt karma-yogo viśiṣyate"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">La <a class=\"t\" href=\"glosario.html#sannyasa\" data-t=\"sannyasa\">renuncia</a> y el <a class=\"t\" href=\"glosario.html#karma-yoga\" data-t=\"karma-yoga\">yoga de la acción</a> llevan ambos al bien supremo; pero, de los dos, el yoga de la acción es superior a la renuncia a la acción.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria) + bhagavat (el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "saṃnyāsaḥ", "sa": "संन्यासः", "gram": "nom. sg. m.", "es": "la renuncia", "ref": "sannyasa"}, {"iast": "karma-yogaḥ", "sa": "कर्मयोगः", "gram": "nom. sg. m. comp.", "es": "el yoga de la acción", "ref": "karma-yoga", "analisis": "karman (acción) + yoga"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "niḥśreyasa-karau", "sa": "निःश्रेयसकरौ", "gram": "nom. du. m. comp.", "es": "que llevan al bien supremo", "analisis": "niḥśreyasa (el bien sin otro mayor: la liberación) + kara (que produce)"}, {"iast": "ubhau", "sa": "उभौ", "gram": "nom. du. m.", "es": "ambos"}, {"iast": "tayoḥ", "sa": "तयोः", "gram": "gen. du. pron.", "es": "de los dos"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "karma-saṃnyāsāt", "sa": "कर्मसंन्यासात्", "gram": "abl. sg. m. comp.", "es": "que la renuncia a la acción", "ref": "sannyasa", "analisis": "karman (acción) + saṃnyāsa (renuncia); ablativo de comparación"}, {"iast": "karma-yogaḥ", "sa": "कर्मयोगः", "gram": "nom. sg. m. comp.", "es": "el yoga de la acción", "ref": "karma-yoga"}, {"iast": "viśiṣyate", "sa": "विशिष्यते", "gram": "3 sg. pres. pas.", "es": "es superior", "analisis": "vi-√śiṣ (distinguir): «se distingue, sobresale»"}], "nota": "<p><em>Niḥśreyasa</em> es «aquello que no tiene nada mejor por encima»: el bien supremo, la liberación. Kṛṣṇa no descalifica la renuncia: las dos vías llevan a la meta. Pero Arjuna ha pedido cuál es mejor, y la respuesta es clara: el yoga de la acción. Los versos siguientes explican por qué no hay contradicción.</p>", "interp": [{"titulo": "Mejor que la renuncia sin conocimiento", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> sostiene que aquí se compara el yoga de la acción con la renuncia de quien todavía no conoce el sí-mismo: para el que ya lo conoce no hay elección, porque el yoga de la acción, que supone creerse agente, es imposible para él. Los dos llevan a la liberación porque hacen nacer el conocimiento, que es lo único que libera; pero la renuncia del que aún no conoce sigue siendo parcial, porque en ella persiste la idea de ser agente, y frente a ella el yoga de la acción es superior por ser más fácil de practicar.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Más fácil y más completo", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende la renuncia como el yoga del conocimiento, la contemplación del sí-mismo, y explica que el yoga de la acción es superior porque es más fácil de practicar y porque contiene ya en sí el conocimiento del sí-mismo.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "El verso de Tilak", "html": "<p>Para <a class=\"t\" href=\"glosario.html#tilak\" data-t=\"tilak\">Tilak</a> el verso es decisivo: Kṛṣṇa no se limita a tolerar la acción, sino que la declara superior a la renuncia, y lo hace al responder a una pregunta directa. En su <em>Gītā-rahasya</em> (1915) lo usó contra la lectura que hace de la renuncia la meta final de la Gītā.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "renunciante-que-actua"}, {"n": 3, "hablante": "krsna", "sa": ["ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति ।", "निर्द्वन्द्वो हि महाबाहो सुखं बन्धात्प्रमुच्यते ॥३॥"], "iast": ["jñeyaḥ sa nitya-saṃnyāsī yo na dveṣṭi na kāṅkṣati", "nirdvandvo hi mahā-bāho sukhaṃ bandhāt pramucyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Ha de tenerse por renunciante constante a quien no odia ni desea; pues, libre de los pares de opuestos, oh <a class=\"t\" href=\"glosario.html#mahabaho\" data-t=\"mahabaho\">Mahābāhu</a>, se libera fácilmente de la atadura.</span>", "palabras": [{"iast": "jñeyaḥ", "sa": "ज्ञेयः", "gram": "nom. sg. m. gerundivo", "es": "ha de ser tenido por", "analisis": "√jñā (conocer): «que ha de conocerse»"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}, {"iast": "nitya-saṃnyāsī", "sa": "नित्यसंन्यासी", "gram": "nom. sg. m. comp.", "es": "renunciante constante", "ref": "sannyasa", "analisis": "nitya (siempre, constante) + saṃnyāsin (renunciante)"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "el que"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "dveṣṭi", "sa": "द्वेष्टि", "gram": "3 sg. pres. act.", "es": "odia", "analisis": "√dviṣ (odiar)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "ni"}, {"iast": "kāṅkṣati", "sa": "काङ्क्षति", "gram": "3 sg. pres. act.", "es": "desea", "analisis": "√kāṅkṣ (anhelar)"}, {"iast": "nirdvandvaḥ", "sa": "निर्द्वन्द्वः", "gram": "nom. sg. m. adj.", "es": "libre de los pares de opuestos", "analisis": "nis (sin) + dvandva (par: calor y frío, placer y dolor…)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "mahā-bāho", "sa": "महाबाहो", "gram": "voc. sg. m. comp.", "es": "oh Mahābāhu", "ref": "mahabaho", "analisis": "mahā (grande) + bāhu (brazo): «el de brazos poderosos»"}, {"iast": "sukham", "sa": "सुखम्", "gram": "ind.", "es": "fácilmente", "analisis": "ac. n. de sukha (bienestar) usado como adverbio"}, {"iast": "bandhāt", "sa": "बन्धात्", "gram": "abl. sg. m.", "es": "de la atadura", "analisis": "√bandh (atar)"}, {"iast": "pramucyate", "sa": "प्रमुच्यते", "gram": "3 sg. pres. pas.", "es": "se libera", "analisis": "pra-√muc (soltar)"}], "nota": "<p><em>Nitya-saṃnyāsin</em>, «renunciante constante»: el que es renunciante siempre, aunque no haya tomado el hábito ni abandonado el hogar. La renuncia se define por dentro, por la ausencia de aversión y de deseo, y no por el estado de vida. Los «pares de opuestos» son los de <a class=\"vref\" href=\"capitulo-02.html#v14\" data-v=\"2.14\">2.14</a> (frío y calor, placer y dolor) y <a class=\"vref\" href=\"capitulo-04.html#v22\" data-v=\"4.22\">4.22</a> (éxito y fracaso); estar libre de ellos (<em>nirdvandva</em>) es lo que Kṛṣṇa pedía a Arjuna en <a class=\"vref\" href=\"capitulo-02.html#v45\" data-v=\"2.45\">2.45</a>.</p>", "interp": [{"titulo": "El renunciante que no ha dejado nada", "html": "<p>El verso redefine al renunciante sin cambiar la palabra: no es quien ha dejado de actuar, sino quien ya no odia ni desea. La misma idea vuelve en <a class=\"vref\" href=\"capitulo-06.html#v1\" data-v=\"6.1\">6.1</a> («el que hace lo que debe hacer sin depender del fruto de la acción, ése es renunciante y yogui») y en el capítulo 18. Por eso puede decir Kṛṣṇa que el yoga de la acción es superior: contiene ya la renuncia que importa.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "renunciante-que-actua"}, {"n": 4, "hablante": "krsna", "sa": ["साङ्ख्ययोगौ पृथग्बालाः प्रवदन्ति न पण्डिताः ।", "एकमप्यास्थितः सम्यगुभयोर्विन्दते फलम् ॥४॥"], "iast": ["sāṅkhya-yogau pṛthag bālāḥ pravadanti na paṇḍitāḥ", "ekam apy āsthitaḥ samyag ubhayor vindate phalam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Que el <a class=\"t\" href=\"glosario.html#sankhya\" data-t=\"sankhya\">sāṅkhya</a> y el yoga son distintos lo dicen los ingenuos, no los sabios: quien se establece bien en uno solo obtiene el <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a> de ambos.</span>", "palabras": [{"iast": "sāṅkhya-yogau", "sa": "साङ्ख्ययोगौ", "gram": "ac. du. m. comp.", "es": "el sāṅkhya y el yoga", "ref": "sankhya", "analisis": "sāṅkhya + yoga (dvandva)"}, {"iast": "pṛthak", "sa": "पृथक्", "gram": "ind.", "es": "distintos, por separado"}, {"iast": "bālāḥ", "sa": "बालाः", "gram": "nom. pl. m.", "es": "los ingenuos", "analisis": "bāla: «niño»"}, {"iast": "pravadanti", "sa": "प्रवदन्ति", "gram": "3 pl. pres. act.", "es": "dicen", "analisis": "pra-√vad (declarar)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "paṇḍitāḥ", "sa": "पण्डिताः", "gram": "nom. pl. m.", "es": "los sabios", "analisis": "paṇḍita: «docto, instruido»"}, {"iast": "ekam", "sa": "एकम्", "gram": "ac. sg. m.", "es": "uno solo"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aunque sea"}, {"iast": "āsthitaḥ", "sa": "आस्थितः", "gram": "nom. sg. m. ppp", "es": "establecido en", "analisis": "ā-√sthā (situarse, entregarse a)"}, {"iast": "samyak", "sa": "सम्यक्", "gram": "ind.", "es": "debidamente, bien"}, {"iast": "ubhayoḥ", "sa": "उभयोः", "gram": "gen. du.", "es": "de ambos"}, {"iast": "vindate", "sa": "विन्दते", "gram": "3 sg. pres. med.", "es": "obtiene", "analisis": "√vid (hallar)"}, {"iast": "phalam", "sa": "फलम्", "gram": "ac. sg. n.", "es": "el fruto", "ref": "phala"}], "nota": "<p><em>Bālāḥ</em>, literalmente «los niños»: los que juzgan por la apariencia, sin discernimiento. La apariencia es que una vía deja la acción y la otra la conserva; los sabios ven que conducen al mismo fruto.</p>", "interp": [{"titulo": "El mismo fruto", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, el fruto de ambos es el mismo, la liberación: quien sigue de verdad el yoga de la acción llega, una vez purificada la mente, al conocimiento y a la renuncia que lo acompaña, y así a la meta del que ha renunciado. No son dos caminos paralelos, sino dos tramos del mismo camino.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Antes de las escuelas", "html": "<p>Franklin Edgerton insistió en que <em>sāṅkhya</em> y <em>yoga</em> no designan todavía en la Gītā las escuelas filosóficas clásicas de esos nombres, sino dos métodos: el del conocimiento que discierne y el de la acción disciplinada. Versos como éste, que los declaran uno, sólo se entienden en ese sentido.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Que la renuncia del conocimiento y el yoga de la acción son distintos lo dicen los ingenuos, no los sabios: quien se establece bien en uno solo obtiene el fruto de ambos.", "nota": "<p>Kṛṣṇa responde a una pregunta sobre la renuncia y el yoga de la acción (<a class=\"vref\" href=\"capitulo-05.html#v1\" data-v=\"5.1\">5.1</a>–<a class=\"vref\" href=\"capitulo-05.html#v2\" data-v=\"5.2\">5.2</a>), pero aquí cambia de vocabulario y habla de <em>sāṅkhya</em> y yoga, como en <a class=\"vref\" href=\"capitulo-02.html#v39\" data-v=\"2.39\">2.39</a> y <a class=\"vref\" href=\"capitulo-03.html#v3\" data-v=\"3.3\">3.3</a>. La alternativa hace explícito lo que el contexto sugiere: <em>sāṅkhya</em> nombra la vía del conocimiento, que lleva consigo la renuncia a las acciones, y no la escuela filosófica posterior de ese nombre. La traducción principal conserva el término, como hace el texto.</p>"}], "ens": "sankhya-y-yoga-uno"}, {"n": 5, "hablante": "krsna", "sa": ["यत्साङ्ख्यैः प्राप्यते स्थानं तद्योगैरपि गम्यते ।", "एकं साङ्ख्यं च योगं च यः पश्यति स पश्यति ॥५॥"], "iast": ["yat sāṅkhyaiḥ prāpyate sthānaṃ tad yogair api gamyate", "ekaṃ sāṅkhyaṃ ca yogaṃ ca yaḥ paśyati sa paśyati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El estado que alcanzan los <a class=\"t\" href=\"glosario.html#sankhya\" data-t=\"sankhya\">sāṅkhyas</a> lo alcanzan también los yoguis. Quien ve que el sāṅkhya y el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> son uno, ése ve.</span>", "palabras": [{"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. rel.", "es": "el que"}, {"iast": "sāṅkhyaiḥ", "sa": "साङ्ख्यैः", "gram": "instr. pl. m.", "es": "por los sāṅkhyas", "ref": "sankhya"}, {"iast": "prāpyate", "sa": "प्राप्यते", "gram": "3 sg. pres. pas.", "es": "se alcanza", "analisis": "pra-√āp (alcanzar)"}, {"iast": "sthānam", "sa": "स्थानम्", "gram": "nom. sg. n.", "es": "el lugar, el estado", "analisis": "√sthā (estar)"}, {"iast": "tat", "sa": "तत्", "gram": "nom. sg. n. pron.", "es": "ése"}, {"iast": "yogaiḥ", "sa": "योगैः", "gram": "instr. pl. m.", "es": "por los yoguis", "ref": "yoga", "analisis": "yoga por yogin: «los del yoga», como sāṅkhya por los que lo siguen"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "gamyate", "sa": "गम्यते", "gram": "3 sg. pres. pas.", "es": "se alcanza", "analisis": "√gam (ir)"}, {"iast": "ekam", "sa": "एकम्", "gram": "ac. sg. n.", "es": "uno"}, {"iast": "sāṅkhyam", "sa": "साङ्ख्यम्", "gram": "ac. sg. n.", "es": "el sāṅkhya", "ref": "sankhya"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "yogam", "sa": "योगम्", "gram": "ac. sg. m.", "es": "el yoga", "ref": "yoga"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "el que"}, {"iast": "paśyati", "sa": "पश्यति", "gram": "3 sg. pres. act.", "es": "ve", "analisis": "√paś (ver)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "paśyati", "sa": "पश्यति", "gram": "3 sg. pres. act.", "es": "ve"}], "nota": "<p><em>Sthāna</em>, «lugar» o «estado»: la meta, el bien supremo de <a class=\"vref\" href=\"capitulo-05.html#v2\" data-v=\"5.2\">5.2</a>. «Ése ve» quiere decir «ése ve de verdad»: la fórmula <em>yaḥ paśyati sa paśyati</em> vuelve en <a class=\"vref\" href=\"capitulo-13.html#v27\" data-v=\"13.27\">13.27</a>, aplicada a quien ve al Señor supremo igual en todos los seres.</p>", "interp": [{"titulo": "Los yoguis llegan por el conocimiento", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica que los sāṅkhyas son los renunciantes establecidos en el conocimiento, y que los yoguis, que ofrecen sus acciones al Señor sin buscar el fruto, alcanzan el mismo estado, la liberación, pasando por el conocimiento de la realidad suprema y por la renuncia que lo acompaña, a los que esa acción los conduce.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "sankhya-y-yoga-uno"}, {"n": 6, "hablante": "krsna", "sa": ["संन्यासस्तु महाबाहो दुःखमाप्तुमयोगतः ।", "योगयुक्तो मुनिर्ब्रह्म नचिरेणाधिगच्छति ॥६॥"], "iast": ["saṃnyāsas tu mahā-bāho duḥkham āptum ayogataḥ", "yoga-yukto munir brahma na cireṇādhigacchati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero la <a class=\"t\" href=\"glosario.html#sannyasa\" data-t=\"sannyasa\">renuncia</a>, oh <a class=\"t\" href=\"glosario.html#mahabaho\" data-t=\"mahabaho\">Mahābāhu</a>, es difícil de alcanzar sin yoga; el <a class=\"t\" href=\"glosario.html#muni\" data-t=\"muni\">sabio</a> unido en yoga llega sin tardar a <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>.</span>", "palabras": [{"iast": "saṃnyāsaḥ", "sa": "संन्यासः", "gram": "nom. sg. m.", "es": "la renuncia", "ref": "sannyasa"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "mahā-bāho", "sa": "महाबाहो", "gram": "voc. sg. m. comp.", "es": "oh Mahābāhu", "ref": "mahabaho", "analisis": "mahā (grande) + bāhu (brazo): «el de brazos poderosos»"}, {"iast": "duḥkham", "sa": "दुःखम्", "gram": "ind.", "es": "difícil", "analisis": "ac. n. de duḥkha (dolor, dificultad); también puede leerse «dolor»"}, {"iast": "āptum", "sa": "आप्तुम्", "gram": "inf.", "es": "de alcanzar", "analisis": "√āp (alcanzar)"}, {"iast": "ayogataḥ", "sa": "अयोगतः", "gram": "ind.", "es": "sin yoga", "analisis": "a (sin) + yoga + -tas (desde, por falta de)"}, {"iast": "yoga-yuktaḥ", "sa": "योगयुक्तः", "gram": "nom. sg. m. comp.", "es": "unido en yoga", "ref": "yoga", "analisis": "yoga + yukta (uncido, unido), de √yuj"}, {"iast": "muniḥ", "sa": "मुनिः", "gram": "nom. sg. m.", "es": "el sabio", "ref": "muni"}, {"iast": "brahma", "sa": "ब्रह्म", "gram": "ac. sg. n.", "es": "brahman", "ref": "brahman"}, {"iast": "na cireṇa", "sa": "नचिरेण", "gram": "ind.", "es": "sin tardar", "analisis": "na (no) + cireṇa (instr. de cira, «largo tiempo»)"}, {"iast": "adhigacchati", "sa": "अधिगच्छति", "gram": "3 sg. pres. act.", "es": "alcanza", "analisis": "adhi-√gam (llegar a)"}], "nota": "<p>El verso explica por qué el yoga de la acción es superior (<a class=\"vref\" href=\"capitulo-05.html#v2\" data-v=\"5.2\">5.2</a>): no porque la renuncia sea mala, sino porque sin la disciplina previa no se consigue de verdad. Quien deja la acción sin haber dominado el deseo sólo cambia de lugar, como el que en <a class=\"vref\" href=\"capitulo-03.html#v6\" data-v=\"3.6\">3.6</a> sujeta los sentidos y sigue pensando en sus objetos.</p>", "interp": [{"titulo": "Brahman es aquí la renuncia", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende que la renuncia de este verso es la verdadera, la que acompaña al conocimiento, y que <em>brahman</em> designa aquí precisamente esa renuncia, apoyándose en un texto védico, la <em>Mahānārāyaṇa Upaniṣad</em> («la renuncia es brahman», <em>nyāsa iti brahmā</em>): el yogui purificado por la acción alcanza pronto la renuncia del conocimiento.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Llegar al sí-mismo", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende <em>brahman</em> en este verso como el sí-mismo: el que practica el yoga de la acción alcanza sin tardar la visión de su propio sí-mismo, mientras que quien empieza por el yoga del conocimiento llega con dificultad.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Pero la renuncia, oh Mahābāhu, sin yoga sólo trae sufrimiento; el sabio unido en yoga llega sin tardar a brahman.", "nota": "<p><em>Duḥkham āptum</em> admite dos construcciones. La principal, la más común, toma <em>duḥkham</em> como adverbio: «difícil de alcanzar». La alternativa lo toma como sustantivo, «dolor»: sin la disciplina interior, la renuncia exterior no lleva a la paz, sino a la penalidad. En los dos casos la conclusión es la misma: la renuncia necesita primero el yoga.</p>"}], "ens": "sankhya-y-yoga-uno"}, {"n": 7, "hablante": "krsna", "sa": ["योगयुक्तो विशुद्धात्मा विजितात्मा जितेन्द्रियः ।", "सर्वभूतात्मभूतात्मा कुर्वन्नपि न लिप्यते ॥७॥"], "iast": ["yoga-yukto viśuddhātmā vijitātmā jitendriyaḥ", "sarva-bhūtātma-bhūtātmā kurvann api na lipyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El que está <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a>, de mente purificada, dueño de sí y vencedor de sus <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a>, cuyo <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a> ha llegado a ser el sí-mismo de todos los seres, aunque actúe no se mancha.</span>", "palabras": [{"iast": "yoga-yuktaḥ", "sa": "योगयुक्तः", "gram": "nom. sg. m. comp.", "es": "unido en yoga", "ref": "yukta", "analisis": "yoga + yukta (unido, uncido, de √yuj)"}, {"iast": "viśuddha-ātmā", "sa": "विशुद्धात्मा", "gram": "nom. sg. m. comp.", "es": "de mente purificada", "ref": "atman", "analisis": "viśuddha (purificado, de vi-√śudh) + ātman (aquí, la mente)"}, {"iast": "vijita-ātmā", "sa": "विजितात्मा", "gram": "nom. sg. m. comp.", "es": "que se ha dominado a sí mismo", "ref": "atman", "analisis": "vijita (vencido, dominado, de vi-√ji) + ātman (aquí, el cuerpo o uno mismo)"}, {"iast": "jita-indriyaḥ", "sa": "जितेन्द्रियः", "gram": "nom. sg. m. comp.", "es": "que ha vencido los sentidos", "ref": "indriya", "analisis": "jita (vencido, de √ji) + indriya (sentido)"}, {"iast": "sarva-bhūta-ātma-bhūta-ātmā", "sa": "सर्वभूतात्मभूतात्मा", "gram": "nom. sg. m. comp.", "es": "cuyo sí-mismo ha llegado a ser el sí-mismo de todos los seres", "ref": "atman", "analisis": "sarva (todo) + bhūta (ser) + ātman (sí-mismo) + bhūta (que ha llegado a ser, de √bhū) + ātman"}, {"iast": "kurvan", "sa": "कुर्वन्", "gram": "nom. sg. m. part. pres.", "es": "actuando", "analisis": "√kṛ (hacer)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aunque"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "lipyate", "sa": "लिप्यते", "gram": "3 sg. pres. pas.", "es": "se mancha", "analisis": "√lip (untar, manchar)"}], "nota": "<p>El verso juega con tres usos de <em>ātman</em>: en <em>viśuddhātmā</em> y <em>vijitātmā</em> designa la mente y el cuerpo, o uno mismo como persona (por eso «de mente purificada» y «dueño de sí»); en <em>sarva-bhūtātma-bhūtātmā</em>, el sí-mismo en sentido pleno. La progresión es la de todo el capítulo: disciplina de la mente, del cuerpo y de los sentidos, y por último una visión en la que el propio sí-mismo y el de los demás ya no se separan. «No se mancha» (<em>na lipyate</em>) anuncia la imagen de la hoja de loto de <a class=\"vref\" href=\"capitulo-05.html#v10\" data-v=\"5.10\">5.10</a>; el mismo verbo usó Kṛṣṇa para sí en <a class=\"vref\" href=\"capitulo-04.html#v14\" data-v=\"4.14\">4.14</a>.</p>", "interp": [{"titulo": "El sí-mismo de todos", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende que el sí-mismo de este yogui «se ha vuelto» el de todos los seres, desde Brahmā hasta una brizna de hierba: es el que ve correctamente, para quien no hay un sí-mismo propio distinto del de los demás. Por eso, aunque actúe para el bien del mundo, no queda atado. Glosa además <em>viśuddhātmā</em> como «de mente (<em>sattva</em>) purificada» y <em>vijitātmā</em> como «que ha dominado el cuerpo».</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La escala del capítulo", "html": "<p>Los adjetivos van de lo externo a lo interno y luego más allá de uno mismo: unido en yoga, purificado, dominado, con los sentidos vencidos, y por fin identificado con todos. Es la respuesta concreta a la pregunta de <a class=\"vref\" href=\"capitulo-05.html#v1\" data-v=\"5.1\">5.1</a>: el yoga de la acción, practicado así, desemboca en lo mismo que buscaba la renuncia, una visión que no separa el propio yo del de los demás.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "El que está unido en yoga, de mente purificada, dueño de sí y vencedor de sus sentidos, que ve su sí-mismo igual al de todos los seres, aunque actúe no se mancha.", "nota": "<p>El compuesto <em>sarva-bhūtātma-bhūtātmā</em> puede leerse como identidad («su sí-mismo es el de todos los seres»), que es la lectura de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, o como igualdad de naturaleza («su sí-mismo es como el de todos los seres»), que es la de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>: separados de la naturaleza material, todos los sí-mismos tienen la misma forma, la del conocimiento (véase <a class=\"vref\" href=\"capitulo-04.html#v35\" data-v=\"4.35\">4.35</a>). <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> lo lee de un tercer modo: el «sí-mismo de todos los seres» es el Señor, y el yogui es aquel que lo tiene a él por su <em>ātman</em>, el que lo atrae hacia sí. Muchos lectores modernos le dan además un sentido moral: el que siente a todos los seres como a sí mismo.</p>"}], "ens": "no-hago-nada"}, {"n": 8, "hablante": "krsna", "sa": ["नैव किञ्चित्करोमीति युक्तो मन्येत तत्त्ववित् ।", "पश्यञ्शृण्वन्स्पृशञ्जिघ्रन्नश्नन्गच्छन्स्वपञ्श्वसन् ॥८॥"], "iast": ["naiva kiñcit karomīti yukto manyeta tattva-vit", "paśyañ śṛṇvan spṛśañ jighrann aśnan gacchan svapañ śvasan"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">«No hago nada», piensa el <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">disciplinado</a> que conoce la verdad, aunque vea, oiga, toque, huela, coma, ande, duerma, respire,</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "en verdad"}, {"iast": "kiñcit", "sa": "किञ्चित्", "gram": "ac. sg. n. pron.", "es": "nada (con la negación)"}, {"iast": "karomi", "sa": "करोमि", "gram": "1 sg. pres. act.", "es": "hago", "analisis": "√kṛ (hacer)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cierra la cita)"}, {"iast": "yuktaḥ", "sa": "युक्तः", "gram": "nom. sg. m.", "es": "el disciplinado, el unido en yoga", "ref": "yukta"}, {"iast": "manyeta", "sa": "मन्येत", "gram": "3 sg. opt. med.", "es": "debe pensar, piensa", "analisis": "√man (pensar)"}, {"iast": "tattva-vit", "sa": "तत्त्ववित्", "gram": "nom. sg. m. comp.", "es": "el que conoce la verdad", "analisis": "tattva (la realidad, «lo que eso es», de tad) + vid (que conoce, de √vid)"}, {"iast": "paśyan", "sa": "पश्यन्", "gram": "nom. sg. m. part. pres.", "es": "viendo", "analisis": "√dṛś / paś (ver)"}, {"iast": "śṛṇvan", "sa": "शृण्वन्", "gram": "nom. sg. m. part. pres.", "es": "oyendo", "analisis": "√śru (oír)"}, {"iast": "spṛśan", "sa": "स्पृशन्", "gram": "nom. sg. m. part. pres.", "es": "tocando", "analisis": "√spṛś (tocar)"}, {"iast": "jighran", "sa": "जिघ्रन्", "gram": "nom. sg. m. part. pres.", "es": "oliendo", "analisis": "√ghrā (oler)"}, {"iast": "aśnan", "sa": "अश्नन्", "gram": "nom. sg. m. part. pres.", "es": "comiendo", "analisis": "√aś (comer)"}, {"iast": "gacchan", "sa": "गच्छन्", "gram": "nom. sg. m. part. pres.", "es": "andando", "analisis": "√gam (ir)"}, {"iast": "svapan", "sa": "स्वपन्", "gram": "nom. sg. m. part. pres.", "es": "durmiendo", "analisis": "√svap (dormir)"}, {"iast": "śvasan", "sa": "श्वसन्", "gram": "nom. sg. m. part. pres.", "es": "respirando", "analisis": "√śvas (respirar)"}], "nota": "<p>La frase sigue en el verso siguiente. <em>Tattva-vit</em>, «el que conoce la verdad», es la misma expresión de <a class=\"vref\" href=\"capitulo-03.html#v28\" data-v=\"3.28\">3.28</a>. La lista recorre los cinco sentidos (ver, oír, tocar, oler y, con «comer», gustar) y luego las funciones del cuerpo; el optativo <em>manyeta</em> puede entenderse como descripción («piensa») o como consejo («debe pensar»).</p>", "interp": [{"titulo": "El que ve la inacción en la acción", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, quien conoce así la verdad del sí-mismo ve inacción en toda actividad del cuerpo y de los sentidos, como pedía <a class=\"vref\" href=\"capitulo-04.html#v18\" data-v=\"4.18\">4.18</a>; y concluye que a ese conocedor no le corresponde ya sino la renuncia a toda acción, porque ve que la acción no existe: quien ha descubierto que el agua del espejismo no es agua no sigue yendo hacia ella para beber.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "no-hago-nada"}, {"n": 9, "hablante": "krsna", "sa": ["प्रलपन्विसृजन्गृह्णन्नुन्मिषन्निमिषन्नपि ।", "इन्द्रियाणीन्द्रियार्थेषु वर्तन्त इति धारयन् ॥९॥"], "iast": ["pralapan visṛjan gṛhṇann unmiṣan nimiṣann api", "indriyāṇīndriyārtheṣu vartanta iti dhārayan"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">hable, suelte, agarre, abra o cierre los ojos, teniendo presente que son los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a> los que se mueven entre sus <a class=\"t\" href=\"glosario.html#visaya\" data-t=\"visaya\">objetos</a>.</span>", "palabras": [{"iast": "pralapan", "sa": "प्रलपन्", "gram": "nom. sg. m. part. pres.", "es": "hablando", "analisis": "pra-√lap (hablar, charlar)"}, {"iast": "visṛjan", "sa": "विसृजन्", "gram": "nom. sg. m. part. pres.", "es": "soltando, evacuando", "analisis": "vi-√sṛj (soltar, expulsar)"}, {"iast": "gṛhṇan", "sa": "गृह्णन्", "gram": "nom. sg. m. part. pres.", "es": "tomando, agarrando", "analisis": "√grah (tomar)"}, {"iast": "unmiṣan", "sa": "उन्मिषन्", "gram": "nom. sg. m. part. pres.", "es": "abriendo los ojos", "analisis": "ud-√miṣ (abrir los ojos)"}, {"iast": "nimiṣan", "sa": "निमिषन्", "gram": "nom. sg. m. part. pres.", "es": "cerrando los ojos", "analisis": "ni-√miṣ (cerrar los ojos, parpadear)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun"}, {"iast": "indriyāṇi", "sa": "इन्द्रियाणि", "gram": "nom. pl. n.", "es": "los sentidos", "ref": "indriya"}, {"iast": "indriya-artheṣu", "sa": "इन्द्रियार्थेषु", "gram": "loc. pl. m. comp.", "es": "entre los objetos de los sentidos", "ref": "visaya", "analisis": "indriya (sentido) + artha (objeto)"}, {"iast": "vartante", "sa": "वर्तन्ते", "gram": "3 pl. pres. med.", "es": "se mueven, actúan", "analisis": "√vṛt (girar, moverse)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cierra la cita)"}, {"iast": "dhārayan", "sa": "धारयन्", "gram": "nom. sg. m. part. pres. caus.", "es": "teniendo presente", "analisis": "√dhṛ (sostener), causativo: mantener firme (en la mente)"}], "nota": "<p><em>Visṛjan</em>, «soltando», se refiere tanto a dejar algo de la mano como a la evacuación del cuerpo; <em>gṛhṇan</em>, «agarrando», es su contrario. Hasta el gesto más involuntario, abrir y cerrar los ojos, entra en la lista: nada de lo que hace el cuerpo queda fuera. La fórmula final calca la de <a class=\"vref\" href=\"capitulo-03.html#v28\" data-v=\"3.28\">3.28</a> («son las guṇas las que se mueven entre las guṇas»), con los sentidos en lugar de las guṇas.</p>", "interp": [{"titulo": "Las guṇas y los sentidos", "html": "<p><a class=\"vref\" href=\"capitulo-03.html#v27\" data-v=\"3.27\">3.27</a>–<a class=\"vref\" href=\"capitulo-03.html#v28\" data-v=\"3.28\">3.28</a> atribuían toda acción a las <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a> de la naturaleza; aquí la misma idea se dice en términos de los sentidos y sus objetos, más cercanos a la experiencia diaria. El capítulo 18 lo formulará en negativo: quien se ve a sí mismo como el único agente «no ve», porque su entendimiento no está formado (<a class=\"vref\" href=\"capitulo-18.html#v16\" data-v=\"18.16\">18.16</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Un ejercicio de atención", "html": "<p>Muchos maestros modernos de meditación leen estos dos versos como una práctica concreta: observar las propias acciones mientras se hacen —ver, oír, caminar, respirar— sin añadirles el «yo lo hago». No es dejar de actuar, sino actuar sin el peso del agente, y por eso sin la ansiedad por el resultado.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "no-hago-nada"}, {"n": 10, "hablante": "krsna", "sa": ["ब्रह्मण्याधाय कर्माणि सङ्गं त्यक्त्वा करोति यः ।", "लिप्यते न स पापेन पद्मपत्रमिवाम्भसा ॥१०॥"], "iast": ["brahmaṇy ādhāya karmāṇi saṅgaṃ tyaktvā karoti yaḥ", "lipyate na sa pāpena padma-patram ivāmbhasā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien actúa depositando sus <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a> en <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> y abandonando el apego no se mancha con el <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a>, como la hoja de loto no se moja con el agua.</span>", "palabras": [{"iast": "brahmaṇi", "sa": "ब्रह्मणि", "gram": "loc. sg. n.", "es": "en brahman", "ref": "brahman"}, {"iast": "ādhāya", "sa": "आधाय", "gram": "abs.", "es": "depositando, poniendo", "analisis": "ā-√dhā (poner, depositar)"}, {"iast": "karmāṇi", "sa": "कर्माणि", "gram": "ac. pl. n.", "es": "las acciones", "ref": "karma"}, {"iast": "saṅgam", "sa": "सङ्गम्", "gram": "ac. sg. m.", "es": "el apego", "analisis": "√sañj (adherirse)"}, {"iast": "tyaktvā", "sa": "त्यक्त्वा", "gram": "abs.", "es": "abandonando", "analisis": "√tyaj (abandonar, dejar)"}, {"iast": "karoti", "sa": "करोति", "gram": "3 sg. pres. act.", "es": "actúa", "analisis": "√kṛ (hacer)"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron.", "es": "quien"}, {"iast": "lipyate", "sa": "लिप्यते", "gram": "3 sg. pres. pas.", "es": "se mancha", "analisis": "√lip (untar, manchar)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}, {"iast": "pāpena", "sa": "पापेन", "gram": "instr. sg. n.", "es": "por el pecado", "ref": "papa"}, {"iast": "padma-patram", "sa": "पद्मपत्रम्", "gram": "nom. sg. n. comp.", "es": "la hoja de loto", "analisis": "padma (loto) + patra (hoja)"}, {"iast": "iva", "sa": "इव", "gram": "ind.", "es": "como"}, {"iast": "ambhasā", "sa": "अम्भसा", "gram": "instr. sg. n.", "es": "por el agua"}], "nota": "<p>La hoja de loto (<em>padma-patra</em>) es impermeable: el agua forma gotas sobre ella y resbala sin mojarla, aunque la planta vive en el agua. La imagen dice exactamente lo que el capítulo enseña: no se trata de salir del mundo, sino de estar en él sin que se adhiera. <em>Ādhāya</em>, «depositando», recuerda el «deposita en mí todas tus acciones» de <a class=\"vref\" href=\"capitulo-03.html#v30\" data-v=\"3.30\">3.30</a>. <em>Pāpa</em>, «pecado», en el sentido de la falta que mancha y deja consecuencias.</p>", "interp": [{"titulo": "Como el siervo para su señor", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica <em>brahmaṇi</em> como «en el Señor»: quien actúa pensando «hago esto para él», como un siervo que trabaja para su señor, sin apego ni siquiera a la liberación como fruto, no queda manchado. El fruto de esa acción es sólo la purificación de la mente.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Depositar las acciones en la naturaleza", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> da a <em>brahman</em> el sentido de la naturaleza material, como en <a class=\"vref\" href=\"capitulo-14.html#v3\" data-v=\"14.3\">14.3</a>: los sentidos, que son productos de la naturaleza, son los que actúan; quien deposita en ella la acción y no se cree el agente queda libre de la mancha. Es la continuación directa de <a class=\"vref\" href=\"capitulo-05.html#v8\" data-v=\"5.8\">5.8</a>–<a class=\"vref\" href=\"capitulo-05.html#v9\" data-v=\"5.9\">5.9</a>.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "La hoja de loto en las Upaniṣads", "html": "<p>La imagen no es nueva. La <em>Chāndogya Upaniṣad</em> (4.14.3) dice que, así como el agua no se adhiere a la hoja de loto, la mala acción no se adhiere a quien conoce. La Gītā la toma y la aplica no al que sabe, sino al que actúa sin apego: la convierte en imagen del yoga de la acción. El loto, que nace del barro y florece limpio sobre el agua, se volverá uno de los símbolos más comunes del arte indio.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Quien actúa dejando sus acciones en manos de la naturaleza y abandonando el apego no se mancha con el pecado, como la hoja de loto no se moja con el agua.", "nota": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende aquí <em>brahman</em> como la naturaleza material (<em>prakṛti</em>), apoyándose en <a class=\"vref\" href=\"capitulo-14.html#v3\" data-v=\"14.3\">14.3</a>, donde Kṛṣṇa llama a la naturaleza «el gran brahman»: depositar las acciones en ella es reconocer que las realizan los sentidos, que son transformaciones suyas, y no el sí-mismo, como acaban de decir <a class=\"vref\" href=\"capitulo-05.html#v8\" data-v=\"5.8\">5.8</a>–<a class=\"vref\" href=\"capitulo-05.html#v9\" data-v=\"5.9\">5.9</a>. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, y con él <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, entiende <em>brahman</em> como el Señor, en el sentido de <a class=\"vref\" href=\"capitulo-03.html#v30\" data-v=\"3.30\">3.30</a>: actuar para él.</p>"}], "ens": "hoja-de-loto"}, {"n": 11, "hablante": "krsna", "sa": ["कायेन मनसा बुद्ध्या केवलैरिन्द्रियैरपि ।", "योगिनः कर्म कुर्वन्ति सङ्गं त्यक्त्वात्मशुद्धये ॥११॥"], "iast": ["kāyena manasā buddhyā kevalair indriyair api", "yoginaḥ karma kurvanti saṅgaṃ tyaktvātma-śuddhaye"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Con el cuerpo, con la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a>, con el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> y aun con los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a> solos, los yoguis realizan la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a> abandonando el apego, para purificarse.</span>", "palabras": [{"iast": "kāyena", "sa": "कायेन", "gram": "instr. sg. m.", "es": "con el cuerpo"}, {"iast": "manasā", "sa": "मनसा", "gram": "instr. sg. n.", "es": "con la mente", "ref": "manas"}, {"iast": "buddhyā", "sa": "बुद्ध्या", "gram": "instr. sg. f.", "es": "con el entendimiento", "ref": "buddhi"}, {"iast": "kevalaiḥ", "sa": "केवलैः", "gram": "instr. pl. n. adj.", "es": "solos, meros; (o) libres de todo «mío»", "analisis": "kevala (solo, puro, exclusivo)"}, {"iast": "indriyaiḥ", "sa": "इन्द्रियैः", "gram": "instr. pl. n.", "es": "con los sentidos", "ref": "indriya"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también, aun"}, {"iast": "yoginaḥ", "sa": "योगिनः", "gram": "nom. pl. m.", "es": "los yoguis", "ref": "yoga"}, {"iast": "karma", "sa": "कर्म", "gram": "ac. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "kurvanti", "sa": "कुर्वन्ति", "gram": "3 pl. pres. act.", "es": "realizan", "analisis": "√kṛ (hacer)"}, {"iast": "saṅgam", "sa": "सङ्गम्", "gram": "ac. sg. m.", "es": "el apego", "analisis": "√sañj (adherirse)"}, {"iast": "tyaktvā", "sa": "त्यक्त्वा", "gram": "abs.", "es": "abandonando", "analisis": "√tyaj (abandonar, dejar)"}, {"iast": "ātma-śuddhaye", "sa": "आत्मशुद्धये", "gram": "dat. sg. f. comp.", "es": "para purificarse", "ref": "atman", "analisis": "ātman (uno mismo; para la mayoría de los comentaristas, la mente) + śuddhi (purificación)"}], "nota": "<p>Cuatro instrumentos de la acción: el cuerpo, la mente, el entendimiento y los sentidos. Los yoguis no dejan de usar ninguno, pero quitan el apego; y el fin no es un fruto exterior, sino la purificación (<em>ātma-śuddhi</em>), que aquí, como en <a class=\"vref\" href=\"capitulo-05.html#v7\" data-v=\"5.7\">5.7</a>, toca ante todo a la mente.</p>", "interp": [{"titulo": "La acción que prepara el conocimiento", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, la acción sin apego de los yoguis tiene como fruto la purificación de la mente (<em>sattva-śuddhi</em>); con la mente pura llega el conocimiento, y con él la renuncia a toda acción. Es su lectura constante del yoga de la acción: un medio, no la meta, que es el conocimiento.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Los dos caminos, reconciliados", "html": "<p>El verso responde a la pregunta de <a class=\"vref\" href=\"capitulo-05.html#v1\" data-v=\"5.1\">5.1</a> por la vía de los hechos: los yoguis no renuncian a la acción, sino al apego, y con ello alcanzan lo que la renuncia promete, la pureza interior. Prepara la afirmación de <a class=\"vref\" href=\"capitulo-05.html#v12\" data-v=\"5.12\">5.12</a>: lo que separa al libre del atado no es si actúa, sino si está unido en yoga.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Con el cuerpo, la mente, el entendimiento y los sentidos, libres todos del sentido de lo mío, los yoguis realizan la acción abandonando el apego, para purificarse.", "nota": "<p><em>Kevalaiḥ</em>, «solos», puede ir con «los sentidos» (la acción en que sólo intervienen los sentidos, sin que la mente se implique) o con los cuatro instrumentos a la vez. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo entiende de este segundo modo y lo glosa como «libres del sentido de lo mío»: el yogui actúa con todo su ser, pero pensando «lo hago para el Señor, no para mi provecho».</p>"}], "ens": "hoja-de-loto"}, {"n": 12, "hablante": "krsna", "sa": ["युक्तः कर्मफलं त्यक्त्वा शान्तिमाप्नोति नैष्ठिकीम् ।", "अयुक्तः कामकारेण फले सक्तो निबध्यते ॥१२॥"], "iast": ["yuktaḥ karma-phalaṃ tyaktvā śāntim āpnoti naiṣṭhikīm", "ayuktaḥ kāma-kāreṇa phale sakto nibadhyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">disciplinado</a>, abandonando el <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a> de la acción, alcanza la <a class=\"t\" href=\"glosario.html#santi\" data-t=\"santi\">paz</a> definitiva; el indisciplinado, apegado al fruto por el impulso del <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a>, queda atado.</span>", "palabras": [{"iast": "yuktaḥ", "sa": "युक्तः", "gram": "nom. sg. m.", "es": "el disciplinado, el unido en yoga", "ref": "yukta"}, {"iast": "karma-phalam", "sa": "कर्मफलम्", "gram": "ac. sg. n. comp.", "es": "el fruto de la acción", "ref": "phala", "analisis": "karman (acción) + phala (fruto)"}, {"iast": "tyaktvā", "sa": "त्यक्त्वा", "gram": "abs.", "es": "abandonando", "analisis": "√tyaj (abandonar, dejar)"}, {"iast": "śāntim", "sa": "शान्तिम्", "gram": "ac. sg. f.", "es": "la paz", "ref": "santi"}, {"iast": "āpnoti", "sa": "आप्नोति", "gram": "3 sg. pres. act.", "es": "alcanza", "analisis": "√āp (alcanzar)"}, {"iast": "naiṣṭhikīm", "sa": "नैष्ठिकीम्", "gram": "ac. sg. f. adj.", "es": "firme, definitiva", "analisis": "de niṣṭhā (firmeza, estabilidad, culminación)"}, {"iast": "ayuktaḥ", "sa": "अयुक्तः", "gram": "nom. sg. m.", "es": "el indisciplinado, el no unido", "ref": "yukta", "analisis": "a (no) + yukta"}, {"iast": "kāma-kāreṇa", "sa": "कामकारेण", "gram": "instr. sg. m. comp.", "es": "por el impulso del deseo", "ref": "kama", "analisis": "kāma (deseo) + kāra (acción, impulso, de √kṛ)"}, {"iast": "phale", "sa": "फले", "gram": "loc. sg. n.", "es": "al fruto", "ref": "phala"}, {"iast": "saktaḥ", "sa": "सक्तः", "gram": "nom. sg. m. ppp", "es": "apegado", "analisis": "√sañj (adherirse)"}, {"iast": "nibadhyate", "sa": "निबध्यते", "gram": "3 sg. pres. pas.", "es": "queda atado", "analisis": "ni-√bandh (atar)"}], "nota": "<p><em>Yukta</em> y <em>ayukta</em>: el que está unido en yoga y el que no. La diferencia entre los dos no es lo que hacen, sino cómo lo hacen: uno deja el fruto, el otro se aferra a él. <em>Naiṣṭhikī</em>, de <em>niṣṭhā</em> («firmeza, culminación»), es la paz que ya no se pierde, la que <a class=\"vref\" href=\"capitulo-02.html#v71\" data-v=\"2.71\">2.71</a> prometía al que abandona todos los deseos. <em>Kāma-kāra</em>, «el obrar movido por el deseo».</p>", "interp": [{"titulo": "Una paz que viene por etapas", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende la «paz definitiva» como la liberación, y la presenta como el término de una secuencia: la acción sin apego purifica la mente; la mente pura alcanza el conocimiento; el conocimiento lleva a la renuncia a toda acción, y ésta a la firmeza en el conocimiento (<em>niṣṭhā</em>), de la que nace esa paz; por eso la llama «definitiva» (<em>naiṣṭhikī</em>).</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Atado por el deseo, no por la acción", "html": "<p>El verso resume en dos líneas la doctrina de los capítulos 2 a 5: la acción en sí no ata; ata el deseo que la mueve y se apega a su fruto. Por eso el mismo acto puede liberar a uno y atar a otro.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "hoja-de-loto"}, {"n": 13, "hablante": "krsna", "sa": ["सर्वकर्माणि मनसा संन्यस्यास्ते सुखं वशी ।", "नवद्वारे पुरे देही नैव कुर्वन्न कारयन् ॥१३॥"], "iast": ["sarva-karmāṇi manasā saṃnyasyāste sukhaṃ vaśī", "nava-dvāre pure dehī naiva kurvan na kārayan"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\"><a class=\"t\" href=\"glosario.html#dehin\" data-t=\"dehin\">El que habita el cuerpo</a>, dueño de sí, renuncia con la mente a todas las <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a> y vive feliz en la <a class=\"t\" href=\"glosario.html#nava-dvara\" data-t=\"nava-dvara\">ciudad de nueve puertas</a>, sin actuar ni causar acción.</span>", "palabras": [{"iast": "sarva-karmāṇi", "sa": "सर्वकर्माणि", "gram": "ac. pl. n. comp.", "es": "todas las acciones", "ref": "karma", "analisis": "sarva (todo) + karman (acción)"}, {"iast": "manasā", "sa": "मनसा", "gram": "instr. sg. n.", "es": "con la mente", "ref": "manas"}, {"iast": "saṃnyasya", "sa": "संन्यस्य", "gram": "abs.", "es": "renunciando, habiendo renunciado", "ref": "sannyasa", "analisis": "sam-ni-√as (deponer, dejar a un lado)"}, {"iast": "āste", "sa": "आस्ते", "gram": "3 sg. pres. med.", "es": "vive, permanece", "analisis": "√ās (estar sentado, quedarse)"}, {"iast": "sukham", "sa": "सुखम्", "gram": "adv.", "es": "feliz, a gusto"}, {"iast": "vaśī", "sa": "वशी", "gram": "nom. sg. m. adj.", "es": "dueño de sí", "analisis": "vaśin, de vaśa (dominio, voluntad)"}, {"iast": "nava-dvāre", "sa": "नवद्वारे", "gram": "loc. sg. n. comp.", "es": "de nueve puertas", "ref": "nava-dvara", "analisis": "nava (nueve) + dvāra (puerta)"}, {"iast": "pure", "sa": "पुरे", "gram": "loc. sg. n.", "es": "en la ciudad", "analisis": "pura (ciudad, fortaleza)"}, {"iast": "dehī", "sa": "देही", "gram": "nom. sg. m.", "es": "el que habita el cuerpo", "ref": "dehin", "analisis": "dehin, de deha (cuerpo)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "en absoluto (refuerza la negación)"}, {"iast": "kurvan", "sa": "कुर्वन्", "gram": "nom. sg. m. part. pres. act.", "es": "haciendo, actuando", "analisis": "√kṛ (hacer)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "kārayan", "sa": "कारयन्", "gram": "nom. sg. m. part. pres. caus.", "es": "causando acción, haciendo que se actúe", "analisis": "causativo de √kṛ"}], "nota": "<p><em>Nava-dvāre pure</em>, «en la ciudad de nueve puertas», es el cuerpo, con sus nueve aberturas: los dos ojos, los dos oídos, las dos fosas nasales, la boca y los dos orificios de excreción. La imagen viene de los Vedas y las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a> (véase la ficha). <em>Vaśī</em>, «dueño de sí», es el que tiene los sentidos bajo su dominio.</p><p>La <a class=\"t\" href=\"glosario.html#sannyasa\" data-t=\"sannyasa\">renuncia</a> es aquí «con la mente»: no se abandonan las acciones por fuera, sino la idea de ser su agente. Es la respuesta del capítulo a la pregunta de Arjuna (<a class=\"vref\" href=\"capitulo-05.html#v1\" data-v=\"5.1\">5.1</a>): la renuncia verdadera puede acompañar a la acción. «Sin actuar ni causar acción»: ni obra él mismo ni pone a obrar al cuerpo y a los sentidos (<em>kārayan</em> es causativo, «hacer que se actúe»); lo que actúa es otra cosa, como dirá el verso siguiente.</p>", "interp": [{"titulo": "Habitar el cuerpo sin ser el cuerpo", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> se pregunta qué tiene de particular que el sabio «viva en el cuerpo», si todo ser encarnado vive en él. Responde que el ignorante, que se toma por el conjunto del cuerpo y los sentidos, piensa «estoy en casa, en el suelo, en el asiento», y no puede pensar «estoy en el cuerpo» como quien está en una casa; sólo el que distingue el sí-mismo del cuerpo vive en él así, como en una casa, sin confundirse con ella. Y entiende «sin actuar ni causar acción» como lo propio del sí-mismo: no es que deje de actuar, es que nunca fue agente.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Un eco de la Śvetāśvatara", "html": "<p>El verso comparte tres palabras con la <em>Śvetāśvatara Upaniṣad</em> (3.18): «el encarnado (<em>dehī</em>), cisne en la ciudad de nueve puertas (<em>nava-dvāre pure</em>), revolotea hacia fuera, dueño (<em>vaśī</em>) de todo el mundo». La Upaniṣad habla del sí-mismo universal que se expande por los sentidos; la Gītā recoge la imagen, pero la vuelve hacia dentro: el dueño de la ciudad no sale por sus puertas, vive en ella feliz y en calma.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "renunciar-con-la-mente"}, {"n": 14, "hablante": "krsna", "sa": ["न कर्तृत्वं न कर्माणि लोकस्य सृजति प्रभुः ।", "न कर्मफलसंयोगं स्वभावस्तु प्रवर्तते ॥१४॥"], "iast": ["na kartṛtvaṃ na karmāṇi lokasya sṛjati prabhuḥ", "na karma-phala-saṃyogaṃ svabhāvas tu pravartate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El Señor no crea en el mundo ni el ser autor de los actos, ni los <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">actos</a>, ni la unión de cada acto con su <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a>: es la <a class=\"t\" href=\"glosario.html#svabhava\" data-t=\"svabhava\">naturaleza propia</a> la que actúa.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "kartṛtvam", "sa": "कर्तृत्वम्", "gram": "ac. sg. n.", "es": "el ser autor (de los actos), la condición de agente", "analisis": "kartṛ (agente) + -tva (abstracto)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "karmāṇi", "sa": "कर्माणि", "gram": "ac. pl. n.", "es": "los actos, las acciones", "ref": "karma"}, {"iast": "lokasya", "sa": "लोकस्य", "gram": "gen. sg. m.", "es": "del mundo, de la gente"}, {"iast": "sṛjati", "sa": "सृजति", "gram": "3 sg. pres. act.", "es": "crea", "analisis": "√sṛj (emitir, crear)"}, {"iast": "prabhuḥ", "sa": "प्रभुः", "gram": "nom. sg. m.", "es": "el señor, el dueño", "analisis": "pra-√bhū (prevalecer, tener poder)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "karma-phala-saṃyogam", "sa": "कर्मफलसंयोगम्", "gram": "ac. sg. m. comp.", "es": "la unión de cada acto con su fruto", "ref": "phala", "analisis": "karman (acción) + phala (fruto) + saṃyoga (unión)"}, {"iast": "svabhāvaḥ", "sa": "स्वभावः", "gram": "nom. sg. m.", "es": "la naturaleza propia", "ref": "svabhava", "analisis": "sva (propio) + bhāva (ser, modo de ser)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "sino, en cambio"}, {"iast": "pravartate", "sa": "प्रवर्तते", "gram": "3 sg. pres. med.", "es": "actúa, se pone en marcha", "analisis": "pra-√vṛt (ponerse en movimiento)"}], "nota": "<p>Continúa el verso anterior: si el que habita el cuerpo no actúa ni hace actuar, ¿quién actúa? Responde la segunda mitad: la <a class=\"t\" href=\"glosario.html#svabhava\" data-t=\"svabhava\">naturaleza propia</a>, el modo de ser de cada cual. Es lo que <a class=\"vref\" href=\"capitulo-03.html#v27\" data-v=\"3.27\">3.27</a> decía con otras palabras: las acciones las realizan las <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a> de la <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a>, y sólo el extraviado por el <a class=\"t\" href=\"glosario.html#ahankara\" data-t=\"ahankara\">sentido del yo</a> piensa «yo soy el que hace».</p><p><em>Lokasya</em>, «del mundo», puede entenderse también «de la gente»: ni que los hombres sean autores de sus actos, ni esos actos, ni el encadenamiento de cada acto con su fruto son obra del Señor.</p><p>«El ser autor de los actos» traduce <em>kartṛtva</em>, abstracto de <em>kartṛ</em>, «el que hace» (véase la ficha <a class=\"t\" href=\"glosario.html#kartr\" data-t=\"kartr\">kartṛ</a>); en las notas y los comentarios se llama también «condición de agente». <em>Kartṛtvam</em> y <em>karmāṇi</em>, «los actos», vienen de la misma raíz √kṛ, «hacer», y la traducción conserva ese eco: «autor de los actos… los actos».</p>", "interp": [{"titulo": "La naturaleza es la māyā", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, el <em>prabhu</em> del verso es el sí-mismo, que por sí no hace ni hace hacer, y la «naturaleza propia» que actúa es la <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a> que consiste en la ignorancia (<em>avidyā</em>), la <a class=\"t\" href=\"glosario.html#maya\" data-t=\"maya\">māyā</a> «divina, hecha de las <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>» de la que hablará <a class=\"vref\" href=\"capitulo-07.html#v14\" data-v=\"7.14\">7.14</a>. La acción pertenece a la māyā; el sí-mismo sólo parece actuar.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "¿Quién es responsable?", "html": "<p>Si <em>prabhu</em> es el Señor, como en la traducción principal, el verso, junto con el siguiente, aparta a Dios del bien y del mal que hacen los hombres: no los crea ni los recibe. Contrasta con <a class=\"vref\" href=\"capitulo-18.html#v61\" data-v=\"18.61\">18.61</a>, donde el Señor, situado en el corazón de todos los seres, los hace girar con su māyā «como montados en una máquina». La Gītā sostiene a la vez las dos cosas. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, que lee así el verso, las concilia de este modo: el Señor pone a obrar a cada uno según su naturaleza, movida por una ignorancia sin comienzo, y según sus acciones pasadas, pero no es él quien produce la condición de agente. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> responde de otro modo: los textos que hacen del Señor el que mueve a obrar hablan desde el punto de vista del extraviado; en verdad, ni el individuo actúa ni el Señor lo hace actuar.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "El sí-mismo, dueño del cuerpo, no crea en el mundo ni el ser autor de los actos, ni los actos, ni la unión de cada acto con su fruto: es la naturaleza propia la que actúa.", "nota": "<p><em>Prabhu</em> significa «señor, dueño». Puede ser Dios, como entienden muchas traducciones, o el que habita el cuerpo, el «dueño» de la ciudad de nueve puertas del verso anterior: así lo leen <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, para quienes <em>prabhu</em> es aquí el sí-mismo; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, en cambio, lo entiende como el Señor. En esta lectura, el verso no habla de la relación de Dios con el mundo, sino de la del sí-mismo con sus propias acciones: no es él quien obra.</p>"}], "ens": "quien-actua-es-la-naturaleza"}, {"n": 15, "hablante": "krsna", "sa": ["नादत्ते कस्यचित्पापं न चैव सुकृतं विभुः ।", "अज्ञानेनावृतं ज्ञानं तेन मुह्यन्ति जन्तवः ॥१५॥"], "iast": ["nādatte kasyacit pāpaṃ na caiva sukṛtaṃ vibhuḥ", "ajñānenāvṛtaṃ jñānaṃ tena muhyanti jantavaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\"><a class=\"t\" href=\"glosario.html#vibhu\" data-t=\"vibhu\">El que todo lo penetra</a> no toma para sí el <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a> de nadie, ni tampoco su buena obra. El <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> está cubierto por la <a class=\"t\" href=\"glosario.html#ajnana\" data-t=\"ajnana\">ignorancia</a>, y por eso se extravían las criaturas.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ādatte", "sa": "आदत्ते", "gram": "3 sg. pres. med.", "es": "toma para sí, recibe", "analisis": "ā-√dā (tomar)"}, {"iast": "kasyacit", "sa": "कस्यचित्", "gram": "gen. sg. m. pron.", "es": "de alguien (con «no»: de nadie)", "analisis": "kasya (de quién) + cit (indefinido)"}, {"iast": "pāpam", "sa": "पापम्", "gram": "ac. sg. n.", "es": "el pecado", "ref": "papa"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "tampoco (refuerza)"}, {"iast": "sukṛtam", "sa": "सुकृतम्", "gram": "ac. sg. n.", "es": "la buena obra", "analisis": "su (bien) + kṛta (hecho)"}, {"iast": "vibhuḥ", "sa": "विभुः", "gram": "nom. sg. m.", "es": "el que todo lo penetra", "ref": "vibhu", "analisis": "vi-√bhū (extenderse, llegar a todas partes)"}, {"iast": "ajñānena", "sa": "अज्ञानेन", "gram": "instr. sg. n.", "es": "por la ignorancia", "ref": "ajnana", "analisis": "a (no) + jñāna (conocimiento)"}, {"iast": "āvṛtam", "sa": "आवृतम्", "gram": "nom. sg. n. ppp", "es": "cubierto", "analisis": "ā-√vṛ (cubrir, envolver)"}, {"iast": "jñānam", "sa": "ज्ञानम्", "gram": "nom. sg. n.", "es": "el conocimiento", "ref": "jnana"}, {"iast": "tena", "sa": "तेन", "gram": "instr. sg. n. pron.", "es": "por eso"}, {"iast": "muhyanti", "sa": "मुह्यन्ति", "gram": "3 pl. pres. act.", "es": "se extravían", "ref": "moha", "analisis": "√muh (confundirse, extraviarse)"}, {"iast": "jantavaḥ", "sa": "जन्तवः", "gram": "nom. pl. m.", "es": "las criaturas", "analisis": "jantu, de √jan (nacer)"}], "nota": "<p><em>Ādatte</em>: «toma, recibe, se apropia». <em>Sukṛta</em>, «lo bien hecho», es la buena obra, que produce mérito, frente al <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a>. <em>Vibhu</em>, de vi-√bhū, es «el que se extiende por todas partes»: el omnipresente, y también el poderoso.</p><p>La segunda mitad explica por qué los hombres creen otra cosa: el conocimiento está cubierto por la ignorancia, como el fuego por el humo o el espejo por el polvo (<a class=\"vref\" href=\"capitulo-03.html#v38\" data-v=\"3.38\">3.38</a>), y de ahí el extravío (<em>moha</em>) que lleva a atribuir las acciones al sí-mismo o a Dios.</p>", "interp": [{"titulo": "«Yo hago, yo hago hacer»", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende el conocimiento cubierto como el discernimiento entre el sí-mismo y lo que no lo es, y el extravío de las criaturas como la convicción de ser agentes y gozadores: «hago, hago hacer, gozaré, hago gozar».</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "¿Recibe Dios las ofrendas?", "html": "<p>El verso dice que el Señor no «toma» (<em>ādatte</em>) el mérito de nadie, y en <a class=\"vref\" href=\"capitulo-09.html#v26\" data-v=\"9.26\">9.26</a> Kṛṣṇa dice que acepta y come la hoja, la flor, el fruto o el agua que se le ofrecen con devoción. No hay contradicción si se distingue: lo que el Señor no hace suyo es la cuenta de méritos y faltas de cada uno, que pertenece a quien obra; lo que acepta es el amor con que se ofrece.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "El sí-mismo, que todo lo penetra, no toma para sí el pecado de nadie, ni tampoco su buena obra. El conocimiento está cubierto por la ignorancia, y por eso se extravían las criaturas.", "nota": "<p>Si el <em>prabhu</em> del verso anterior es el sí-mismo (véanse sus alternativas), <em>vibhu</em>, «el que todo lo penetra», puede serlo también: la Gītā llama al sí-mismo «presente en todas partes» (<em>sarva-gataḥ</em>, <a class=\"vref\" href=\"capitulo-02.html#v24\" data-v=\"2.24\">2.24</a>). Así lo lee <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, aunque para él <em>vibhu</em> no quiere decir aquí que el sí-mismo esté en todas partes, sino que no está atado a ningún lugar ni a ningún cuerpo. La traducción principal lo entiende como el Señor, igual que <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y que <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, quien sin embargo ha leído <em>prabhu</em> como el sí-mismo.</p>"}], "ens": "quien-actua-es-la-naturaleza"}, {"n": 16, "hablante": "krsna", "sa": ["ज्ञानेन तु तदज्ञानं येषां नाशितमात्मनः ।", "तेषामादित्यवज्ज्ञानं प्रकाशयति तत्परम् ॥१६॥"], "iast": ["jñānena tu tad ajñānaṃ yeṣāṃ nāśitam ātmanaḥ", "teṣām ādityavaj jñānaṃ prakāśayati tat param"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero en aquellos en quienes el conocimiento del <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a> ha destruido esa ignorancia, el conocimiento, como el sol, ilumina aquello supremo.</span>", "palabras": [{"iast": "jñānena", "sa": "ज्ञानेन", "gram": "instr. sg. n.", "es": "por el conocimiento", "ref": "jnana"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "tat", "sa": "तत्", "gram": "nom. sg. n. pron.", "es": "esa"}, {"iast": "ajñānam", "sa": "अज्ञानम्", "gram": "nom. sg. n.", "es": "la ignorancia", "ref": "ajnana"}, {"iast": "yeṣām", "sa": "येषाम्", "gram": "gen. pl. m. pron.", "es": "de los cuales, en quienes"}, {"iast": "nāśitam", "sa": "नाशितम्", "gram": "nom. sg. n. ppp caus.", "es": "destruida", "analisis": "causativo de √naś (perecer)"}, {"iast": "ātmanaḥ", "sa": "आत्मनः", "gram": "gen. sg. m.", "es": "del sí-mismo", "ref": "atman"}, {"iast": "teṣām", "sa": "तेषाम्", "gram": "gen. pl. m. pron.", "es": "de ellos, en ellos"}, {"iast": "āditya-vat", "sa": "आदित्यवत्", "gram": "ind.", "es": "como el sol", "analisis": "āditya (el sol) + -vat (como)"}, {"iast": "jñānam", "sa": "ज्ञानम्", "gram": "nom. sg. n.", "es": "el conocimiento", "ref": "jnana"}, {"iast": "prakāśayati", "sa": "प्रकाशयति", "gram": "3 sg. pres. caus.", "es": "ilumina, hace visible", "analisis": "pra-√kāś (brillar), causativo"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "aquello"}, {"iast": "param", "sa": "परम्", "gram": "ac. sg. n. adj.", "es": "supremo"}], "nota": "<p><em>Āditya-vat</em>, «como el sol». <em>Tat param</em>, «aquello supremo»: la realidad suprema, sin nombrarla. El conocimiento no fabrica lo que muestra: lo hace visible, como el sol no crea las cosas, sino que las ilumina. La misma imagen vuelve en <a class=\"vref\" href=\"capitulo-13.html#v33\" data-v=\"13.33\">13.33</a>, donde el conocedor del campo ilumina el campo entero como el sol el mundo, y en <a class=\"vref\" href=\"capitulo-10.html#v11\" data-v=\"10.11\">10.11</a>, donde Kṛṣṇa disipa la oscuridad nacida de la ignorancia con la lámpara del conocimiento.</p>", "interp": [{"titulo": "Quitar el velo", "html": "<p>Para la lectura del <a class=\"t\" href=\"glosario.html#advaita\" data-t=\"advaita\">Advaita</a>, el verso describe la liberación como la desaparición de un velo, no como la adquisición de algo nuevo: lo supremo ya estaba ahí, y el conocimiento sólo retira la ignorancia que lo cubría, como el sol, al salir, no produce los objetos, sino que deja verlos.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Del verso 15 al 16", "html": "<p>Los dos versos forman una pareja de oscuridad y luz: en el primero, la ignorancia cubre el conocimiento y las criaturas se extravían; en el segundo, el conocimiento destruye la ignorancia y brilla como el sol. El verbo final, <em>prakāśayati</em>, «ilumina», cierra con una imagen la doctrina abstracta de los versos anteriores.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Pero en aquellos que, con el conocimiento, han destruido la ignorancia de su propio ser, el conocimiento, como el sol, ilumina aquello supremo.", "nota": "<p>El genitivo <em>ātmanaḥ</em>, «del sí-mismo», puede ir con «conocimiento» (el conocimiento del sí-mismo destruye la ignorancia) o con «ignorancia» (la ignorancia que uno tiene de sí mismo es la que se destruye). El sentido de conjunto apenas cambia: en los dos casos, lo que se ignoraba y lo que se llega a conocer es el sí-mismo.</p>"}], "ens": "el-conocimiento-como-el-sol"}, {"n": 17, "hablante": "krsna", "sa": ["तद्बुद्धयस्तदात्मानस्तन्निष्ठास्तत्परायणाः ।", "गच्छन्त्यपुनरावृत्तिं ज्ञाननिर्धूतकल्मषाः ॥१७॥"], "iast": ["tad-buddhayas tad-ātmānas tan-niṣṭhās tat-parāyaṇāḥ", "gacchanty apunar-āvṛttiṃ jñāna-nirdhūta-kalmaṣāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Con el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> puesto en aquello supremo, unidos a ello en su ser, asentados en ello y entregados a ello por entero, van adonde ya no se vuelve, limpios de impurezas por el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>.</span>", "palabras": [{"iast": "tad-buddhayaḥ", "sa": "तद्बुद्धयः", "gram": "nom. pl. m. comp.", "es": "con el entendimiento puesto en aquello", "ref": "buddhi", "analisis": "tat (aquello) + buddhi (entendimiento)"}, {"iast": "tad-ātmānaḥ", "sa": "तदात्मानः", "gram": "nom. pl. m. comp.", "es": "cuyo ser es aquello; con la mente en aquello", "ref": "atman", "analisis": "tat (aquello) + ātman (sí-mismo)"}, {"iast": "tan-niṣṭhāḥ", "sa": "तन्निष्ठाः", "gram": "nom. pl. m. comp.", "es": "asentados en aquello", "analisis": "tat (aquello) + niṣṭhā (firmeza, asiento)"}, {"iast": "tat-parāyaṇāḥ", "sa": "तत्परायणाः", "gram": "nom. pl. m. comp.", "es": "que tienen aquello por meta suprema", "analisis": "tat (aquello) + parāyaṇa (refugio, meta última)"}, {"iast": "gacchanti", "sa": "गच्छन्ति", "gram": "3 pl. pres. act.", "es": "van", "analisis": "√gam (ir)"}, {"iast": "apunar-āvṛttim", "sa": "अपुनरावृत्तिम्", "gram": "ac. sg. f. comp.", "es": "al no-retorno", "ref": "samsara", "analisis": "a (no) + punar (de nuevo) + āvṛtti (vuelta)"}, {"iast": "jñāna-nirdhūta-kalmaṣāḥ", "sa": "ज्ञाननिर्धूतकल्मषाः", "gram": "nom. pl. m. comp.", "es": "con las impurezas sacudidas por el conocimiento", "ref": "jnana", "analisis": "jñāna (conocimiento) + nirdhūta (sacudido, de nis-√dhū) + kalmaṣa (impureza)"}], "nota": "<p>«Aquello» (<em>tat</em>, pronombre neutro) es «aquello supremo» del verso anterior (<em>tat param</em>, <a class=\"vref\" href=\"capitulo-05.html#v16\" data-v=\"5.16\">5.16</a>); la traducción repite «supremo», que el verso no dice, para que se vea a qué se refiere, y sigue con «ello», neutro como el sánscrito, que no decide si se trata de brahman, del Señor o del sí-mismo. Los cuatro compuestos van de dentro afuera y de abajo arriba: el entendimiento, el ser entero (<em>ātman</em>), la firmeza de la vida (<em>niṣṭhā</em>) y la meta última (<em>parāyaṇa</em>) se vuelven hacia lo mismo.</p><p><em>Apunar-āvṛtti</em>, «el no-retorno», es la salida del <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">ciclo de renacimientos</a>: el lugar «del que no se vuelve» de <a class=\"vref\" href=\"capitulo-08.html#v16\" data-v=\"8.16\">8.16</a>–<a class=\"vref\" href=\"capitulo-08.html#v21\" data-v=\"8.21\">8.21</a> y <a class=\"vref\" href=\"capitulo-15.html#v6\" data-v=\"15.6\">15.6</a>. <em>Nirdhūta</em> es «sacudido», como se sacude el polvo; las impurezas (<em>kalmaṣa</em>) eran las de <a class=\"vref\" href=\"capitulo-04.html#v30\" data-v=\"4.30\">4.30</a>.</p>", "interp": [{"titulo": "Eso es brahman", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> identifica el «eso» con el <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> supremo: <em>tad-ātmānaḥ</em> son aquellos cuyo sí-mismo es ese mismo brahman, y <em>tan-niṣṭhāḥ</em>, los que, habiendo renunciado a todas las acciones, permanecen sólo en él.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Aquello es el sí-mismo", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, «aquello» no es aquí brahman, sino el propio sí-mismo, visto en su naturaleza pura, que es de lo que trata el capítulo. Los cuatro compuestos describen la práctica que lleva a esa visión: <em>tad-buddhayaḥ</em> son los que se han resuelto a ver el sí-mismo tal como es; <em>tad-ātmānaḥ</em>, los que tienen la mente puesta en él; <em>tan-niṣṭhāḥ</em>, los que se dedican a ejercitarse en ello; <em>tat-parāyaṇāḥ</em>, los que lo tienen por meta suprema. Con ese conocimiento, ejercitado, sacuden las impurezas acumuladas desde antiguo y «van al no-retorno», que Rāmānuja entiende como el sí-mismo establecido en su forma propia, estado del que ya no se vuelve.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "¿Brahman, el Señor o el sí-mismo?", "html": "<p>El verso no nombra lo que es «aquello», y los comentaristas lo llenan de modo distinto: brahman supremo para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, el sí-mismo para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, el Señor (<em>īśvara</em>) para <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, que ve en el verso el fruto de venerarlo: por su gracia se alcanza el conocimiento del sí-mismo que sacude las impurezas.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Cuatro veces «aquello»", "html": "<p>La repetición de <em>tat</em> en cuatro compuestos seguidos es un recurso de intensidad: el verso no añade ideas nuevas, sino que muestra a la persona entera —pensamiento, ser, conducta y meta— orientada hacia un solo punto. La Gītā usará el mismo recurso, con «yo» en lugar de «eso», en <a class=\"vref\" href=\"capitulo-09.html#v34\" data-v=\"9.34\">9.34</a>: «pon en mí tu mente, sé mi devoto…».</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Con el entendimiento puesto en aquello supremo, con la mente puesta en ello, asentados en ello y entregados a ello por entero, van adonde ya no se vuelve, limpios de impurezas por el conocimiento.", "nota": "<p><em>Ātman</em> tiene aquí dos lecturas. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo entienden como el sí-mismo: <em>tad-ātmānaḥ</em> son «aquellos cuyo sí-mismo es ese mismo brahman supremo». <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> lo entienden como la mente (<em>manas</em>), sentido que <em>ātman</em> tiene a veces en la Gītā: «aquellos cuya mente está en ello». La traducción principal, «unidos a ello en su ser», queda entre las dos.</p>"}], "ens": "el-conocimiento-como-el-sol"}, {"n": 18, "hablante": "krsna", "sa": ["विद्याविनयसम्पन्ने ब्राह्मणे गवि हस्तिनि ।", "शुनि चैव श्वपाके च पण्डिताः समदर्शिनः ॥१८॥"], "iast": ["vidyā-vinaya-sampanne brāhmaṇe gavi hastini", "śuni caiva śva-pāke ca paṇḍitāḥ sama-darśinaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los sabios ven con la misma mirada al <a class=\"t\" href=\"glosario.html#brahmana\" data-t=\"brahmana\">brahmán</a> dotado de saber y de modestia, a la vaca, al elefante, al perro y al <a class=\"t\" href=\"glosario.html#svapaka\" data-t=\"svapaka\">paria</a>.</span>", "palabras": [{"iast": "vidyā-vinaya-sampanne", "sa": "विद्याविनयसम्पन्ने", "gram": "loc. sg. m. comp.", "es": "dotado de saber y de modestia", "analisis": "vidyā (saber) + vinaya (modestia, buena educación; de vi-√nī «guiar») + sampanna (dotado, de sam-√pad)"}, {"iast": "brāhmaṇe", "sa": "ब्राह्मणे", "gram": "loc. sg. m.", "es": "en el brahmán", "ref": "brahmana"}, {"iast": "gavi", "sa": "गवि", "gram": "loc. sg. f.", "es": "en la vaca", "analisis": "go (vaca, buey)"}, {"iast": "hastini", "sa": "हस्तिनि", "gram": "loc. sg. m.", "es": "en el elefante", "analisis": "hastin «el que tiene mano» (hasta), por la trompa"}, {"iast": "śuni", "sa": "शुनि", "gram": "loc. sg. m.", "es": "en el perro", "analisis": "śvan (perro)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "también, incluso"}, {"iast": "śva-pāke", "sa": "श्वपाके", "gram": "loc. sg. m. comp.", "es": "en el paria (lit. «el que cuece perros»)", "ref": "svapaka", "analisis": "śvan (perro) + pāka (que cuece, de √pac «cocer»)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "paṇḍitāḥ", "sa": "पण्डिताः", "gram": "nom. pl. m.", "es": "los sabios", "analisis": "paṇḍita (docto, sabio)"}, {"iast": "sama-darśinaḥ", "sa": "समदर्शिनः", "gram": "nom. pl. m. comp.", "es": "ven con la misma mirada", "ref": "samatva", "analisis": "sama (igual) + darśin (que ve, de √dṛś «ver»)"}], "nota": "<p>La enumeración baja de lo más alto a lo más bajo y mezcla hombres y animales: el brahmán instruido, la vaca, sagrada, el elefante, noble, el perro, impuro, y el <em>śva-pāka</em>, literalmente «el que cuece perros» (véanse las alternativas y la ficha <a class=\"t\" href=\"glosario.html#svapaka\" data-t=\"svapaka\">śva-pāka</a>). <em>Sama-darśin</em> es «el que ve igual»: la igualdad no está en los seres, que siguen siendo distintos, sino en la mirada del sabio, y el verso siguiente dice por qué.</p>", "interp": [{"titulo": "Un mismo brahman bajo las tres guṇas", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> relaciona los ejemplos con las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>: el brahmán instruido es el ser <em>sāttvika</em>; la vaca, el <em>rājasa</em>; el elefante, el perro y el paria, los <em>tāmasa</em>. El sabio ve en todos el mismo brahman, uno e inmutable, al que no tocan ni las guṇas ni las impresiones que dejan.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Los sí-mismos son iguales", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lo entiende de los sí-mismos: las diferencias entre el brahmán, el animal y el paria son del cuerpo, que pertenece a la <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a>; separados de ella, todos los sí-mismos tienen la misma forma, la del conocimiento, y por eso el sabio los ve iguales.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Igualdad de mirada, no de orden social", "html": "<p>El verso describe cómo ve el sabio, no un programa social: la misma Gītā mantiene las cuatro clases (<a class=\"vref\" href=\"capitulo-04.html#v13\" data-v=\"4.13\">4.13</a>), y en la tradición clásica la igualdad de la mirada convivió con las distinciones de clase en la vida ritual y social. A partir del siglo XIX, en cambio, reformadores hindúes lo han citado contra la exclusión de los llamados intocables: Vivekananda lo invocó en Londres contra el privilegio del brahmán que se aparta en la calle para que no lo toque un hombre de casta baja, y <a class=\"t\" href=\"glosario.html#gandhi\" data-t=\"gandhi\">Gandhi</a>, en su <em>Anāsakti-yoga</em>, lo glosó como el deber de servir igual al brahmán y al paria.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Los sabios ven con la misma mirada al brahmán dotado de saber y de modestia, a la vaca, al elefante, al perro y al que cuece perros.", "nota": "<p>Traducción literal de <em>śva-pāka</em>, «el que cuece (y come) perros», nombre despectivo de los grupos más despreciados, fuera de las cuatro clases. El texto elige a propósito el extremo más bajo de la escala social para oponerlo al brahmán instruido. «Paria», que esta edición prefiere por ser la palabra común en español, conserva el sentido social, pero pierde la crudeza de la imagen.</p>"}], "ens": "la-misma-mirada"}, {"n": 19, "hablante": "krsna", "sa": ["इहैव तैर्जितः सर्गो येषां साम्ये स्थितं मनः ।", "निर्दोषं हि समं ब्रह्म तस्माद्ब्रह्मणि ते स्थिताः ॥१९॥"], "iast": ["ihaiva tair jitaḥ sargo yeṣāṃ sāmye sthitaṃ manaḥ", "nirdoṣaṃ hi samaṃ brahma tasmād brahmaṇi te sthitāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Aquí mismo han vencido el ciclo de los nacimientos aquellos cuya <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> está asentada en la igualdad; pues <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> es igual y sin defecto, y por eso ellos están asentados en brahman.</span>", "palabras": [{"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "mismo"}, {"iast": "taiḥ", "sa": "तैः", "gram": "ins. pl. m.", "es": "por ellos"}, {"iast": "jitaḥ", "sa": "जितः", "gram": "nom. sg. m. part.", "es": "vencido", "analisis": "√ji (vencer)"}, {"iast": "sargaḥ", "sa": "सर्गः", "gram": "nom. sg. m.", "es": "la creación; aquí, el ciclo de los nacimientos", "analisis": "de √sṛj (soltar, emitir, crear)"}, {"iast": "yeṣām", "sa": "येषाम्", "gram": "gen. pl. m.", "es": "de quienes"}, {"iast": "sāmye", "sa": "साम्ये", "gram": "loc. sg. n.", "es": "en la igualdad", "ref": "samatva", "analisis": "sāmya, abstracto de sama (igual)"}, {"iast": "sthitam", "sa": "स्थितम्", "gram": "nom. sg. n. part.", "es": "asentada", "analisis": "√sthā (estar de pie, permanecer)"}, {"iast": "manaḥ", "sa": "मनः", "gram": "nom. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "nirdoṣam", "sa": "निर्दोषम्", "gram": "nom. sg. n. adj.", "es": "sin defecto", "analisis": "nis (sin) + doṣa (defecto, falta)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "samam", "sa": "समम्", "gram": "nom. sg. n. adj.", "es": "igual"}, {"iast": "brahma", "sa": "ब्रह्म", "gram": "nom. sg. n.", "es": "brahman", "ref": "brahman"}, {"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg.", "es": "por eso"}, {"iast": "brahmaṇi", "sa": "ब्रह्मणि", "gram": "loc. sg. n.", "es": "en brahman"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m.", "es": "ellos"}, {"iast": "sthitāḥ", "sa": "स्थिताः", "gram": "nom. pl. m. part.", "es": "están asentados"}], "nota": "<p><em>Iha eva</em>, «aquí mismo»: en esta vida, sin esperar a la muerte. <em>Sāmya</em>, «igualdad», es el estado de quien ve con la misma mirada (<a class=\"vref\" href=\"capitulo-05.html#v18\" data-v=\"5.18\">5.18</a>), y el verso da su razón: brahman mismo es <em>sama</em>, igual en todos, y <em>nirdoṣa</em>, sin defecto. Quien se asienta en la igualdad se asienta, por eso, en brahman.</p>", "interp": [{"titulo": "Vencer el nacimiento en vida", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> glosa <em>sarga</em> como «nacimiento» y entiende que los que ven con igualdad están liberados ya en esta vida. Brahman es «sin defecto» porque, aunque los ignorantes lo crean manchado cuando está en el paria y en otros seres impuros, sus defectos no lo tocan; y es «igual» y uno porque, sin cualidades, nada lo divide de un cuerpo a otro.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El sí-mismo, igual en todos", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende aquí <em>brahman</em> como el sí-mismo libre de la naturaleza material, que es igual en todos los seres: asentarse en esa igualdad es asentarse en brahman. Y lo vencido es el <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">ciclo de renacimientos</a>.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Aquí mismo han vencido la creación aquellos cuya mente está asentada en la igualdad; pues brahman es igual y sin defecto, y por eso ellos están asentados en brahman.", "nota": "<p>Literal: <em>sarga</em> es «creación, emisión» (de √sṛj, «soltar, emitir»), el mundo creado. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo glosa como «nacimiento» (<em>janma</em>), y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> como el ciclo de renacimientos (<em>saṃsāra</em>); esta edición los sigue: quienes viven en la igualdad han vencido ya, en vida, la necesidad de renacer. Leído a la letra, el verso dice que han vencido el mundo de lo creado.</p>"}], "ens": "la-misma-mirada"}, {"n": 20, "hablante": "krsna", "sa": ["न प्रहृष्येत्प्रियं प्राप्य नोद्विजेत्प्राप्य चाप्रियम् ।", "स्थिरबुद्धिरसम्मूढो ब्रह्मविद्ब्रह्मणि स्थितः ॥२०॥"], "iast": ["na prahṛṣyet priyaṃ prāpya nodvijet prāpya cāpriyam", "sthira-buddhir asammūḍho brahma-vid brahmaṇi sthitaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">No se exalta al obtener lo agradable ni se turba al recibir lo desagradable: de <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> firme y sin <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extravío</a>, el que conoce <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> está asentado en brahman.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "prahṛṣyet", "sa": "प्रहृष्येत्", "gram": "3 sg. opt.", "es": "se exalte", "analisis": "pra-√hṛṣ (alegrarse, excitarse)"}, {"iast": "priyam", "sa": "प्रियम्", "gram": "ac. sg. n.", "es": "lo agradable"}, {"iast": "prāpya", "sa": "प्राप्य", "gram": "abs.", "es": "al obtener", "analisis": "pra-√āp (alcanzar)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "udvijet", "sa": "उद्विजेत्", "gram": "3 sg. opt.", "es": "se turbe", "analisis": "ud-√vij (estremecerse, inquietarse)"}, {"iast": "prāpya", "sa": "प्राप्य", "gram": "abs.", "es": "al recibir"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "apriyam", "sa": "अप्रियम्", "gram": "ac. sg. n.", "es": "lo desagradable"}, {"iast": "sthira-buddhiḥ", "sa": "स्थिरबुद्धिः", "gram": "nom. sg. m. comp.", "es": "de entendimiento firme", "ref": "buddhi", "analisis": "sthira (firme) + buddhi (entendimiento)"}, {"iast": "asammūḍhaḥ", "sa": "असम्मूढः", "gram": "nom. sg. m. adj.", "es": "sin extravío", "ref": "moha", "analisis": "a (no) + sam-mūḍha (extraviado, de √muh)"}, {"iast": "brahma-vid", "sa": "ब्रह्मविद्", "gram": "nom. sg. m. comp.", "es": "el que conoce brahman", "analisis": "brahman + vid (que conoce, de √vid «saber»)"}, {"iast": "brahmaṇi", "sa": "ब्रह्मणि", "gram": "loc. sg. n.", "es": "en brahman", "ref": "brahman"}, {"iast": "sthitaḥ", "sa": "स्थितः", "gram": "nom. sg. m. part.", "es": "asentado"}], "nota": "<p>Los verbos están en optativo, «no ha de exaltarse», «no ha de turbarse», que en estas descripciones vale a la vez como retrato y como norma. <em>Sthira-buddhi</em>, «de entendimiento firme», recuerda al <a class=\"t\" href=\"glosario.html#sthitaprajna\" data-t=\"sthitaprajna\">de sabiduría firme</a> del capítulo 2, que ni se alegra ni se aflige con lo bueno o lo malo que le llega (<a class=\"vref\" href=\"capitulo-02.html#v56\" data-v=\"2.56\">2.56</a>–<a class=\"vref\" href=\"capitulo-02.html#v57\" data-v=\"2.57\">2.57</a>).</p>", "interp": [{"titulo": "El de sabiduría firme, otra vez", "html": "<p>El verso condensa el retrato del sabio de <a class=\"vref\" href=\"capitulo-02.html#v55\" data-v=\"2.55\">2.55</a>–<a class=\"vref\" href=\"capitulo-02.html#v72\" data-v=\"2.72\">2.72</a> y le da un nuevo fundamento: la estabilidad ante lo agradable y lo desagradable ya no es sólo dominio de sí, sino la señal de quien «conoce brahman» y «está asentado en brahman». El capítulo 2 terminaba igual, con el «estado de brahman» (<a class=\"vref\" href=\"capitulo-02.html#v72\" data-v=\"2.72\">2.72</a>); el 5 lo retomará como «la extinción en brahman» (<a class=\"vref\" href=\"capitulo-05.html#v24\" data-v=\"5.24\">5.24</a>–<a class=\"vref\" href=\"capitulo-05.html#v26\" data-v=\"5.26\">5.26</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-misma-mirada"}, {"n": 21, "hablante": "krsna", "sa": ["बाह्यस्पर्शेष्वसक्तात्मा विन्दत्यात्मनि यत्सुखम् ।", "स ब्रह्मयोगयुक्तात्मा सुखमक्षयमश्नुते ॥२१॥"], "iast": ["bāhya-sparśeṣv asaktātmā vindaty ātmani yat sukham", "sa brahma-yoga-yuktātmā sukham akṣayam aśnute"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien no se apega a los <a class=\"t\" href=\"glosario.html#sparsa\" data-t=\"sparsa\">contactos</a> externos halla la dicha que hay en el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>; unido a <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> por el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>, goza de una dicha que no se agota.</span>", "palabras": [{"iast": "bāhya-sparśeṣu", "sa": "बाह्यस्पर्शेषु", "gram": "loc. pl. m. comp.", "es": "a los contactos externos", "ref": "sparsa", "analisis": "bāhya (externo) + sparśa (contacto, de √spṛś «tocar»)"}, {"iast": "asakta-ātmā", "sa": "असक्तात्मा", "gram": "nom. sg. m. comp.", "es": "el de ánimo no apegado", "analisis": "a (no) + sakta (apegado, de √sañj) + ātman (aquí, la mente o el ánimo)"}, {"iast": "vindati", "sa": "विन्दति", "gram": "3 sg. pres.", "es": "halla", "analisis": "√vid (hallar)"}, {"iast": "ātmani", "sa": "आत्मनि", "gram": "loc. sg. m.", "es": "en el sí-mismo", "ref": "atman"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. rel.", "es": "que"}, {"iast": "sukham", "sa": "सुखम्", "gram": "ac. sg. n.", "es": "la dicha"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m.", "es": "él"}, {"iast": "brahma-yoga-yukta-ātmā", "sa": "ब्रह्मयोगयुक्तात्मा", "gram": "nom. sg. m. comp.", "es": "con el ánimo unido a brahman por el yoga", "analisis": "brahman + yoga + yukta (unido, de √yuj) + ātman (ánimo)"}, {"iast": "sukham", "sa": "सुखम्", "gram": "ac. sg. n.", "es": "una dicha"}, {"iast": "akṣayam", "sa": "अक्षयम्", "gram": "ac. sg. n. adj.", "es": "que no se agota", "analisis": "a (no) + kṣaya (agotamiento, de √kṣi «destruir»)"}, {"iast": "aśnute", "sa": "अश्नुते", "gram": "3 sg. pres.", "es": "alcanza, goza", "analisis": "√aś (alcanzar)"}], "nota": "<p><em>Bāhya-sparśa</em>: los contactos de los sentidos con los objetos de fuera (véase <a class=\"vref\" href=\"capitulo-02.html#v14\" data-v=\"2.14\">2.14</a>). En <em>asaktātmā</em> y <em>brahma-yoga-yuktātmā</em>, <em>ātman</em> tiene el sentido de «mente» o «ánimo»: «el de ánimo no apegado», «el de ánimo unido a brahman por el yoga». En <em>ātmani yat sukham</em>, «la dicha que hay en el <em>ātman</em>», puede entenderse «en sí mismo» o «en el sí-mismo»; esta edición elige lo segundo, porque es la dicha que se opone a la que llega de fuera.</p>", "interp": [{"titulo": "Dos contactos", "html": "<p>El verso abre un contraste que la Gītā cerrará en <a class=\"vref\" href=\"capitulo-06.html#v28\" data-v=\"6.28\">6.28</a>: frente a los contactos externos, cuya dicha se agota (<a class=\"vref\" href=\"capitulo-05.html#v22\" data-v=\"5.22\">5.22</a>), el yogui alcanza la dicha sin límite del «contacto con brahman» (<em>brahma-saṃsparśa</em>). La misma palabra, «contacto», nombra la atadura y la liberación. La dicha «en el sí-mismo» recuerda también al sabio de <a class=\"vref\" href=\"capitulo-02.html#v55\" data-v=\"2.55\">2.55</a>, «contento en el sí-mismo por el sí-mismo».</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "resistir-el-impetu"}, {"n": 22, "hablante": "krsna", "sa": ["ये हि संस्पर्शजा भोगा दुःखयोनय एव ते ।", "आद्यन्तवन्तः कौन्तेय न तेषु रमते बुधः ॥२२॥"], "iast": ["ye hi saṃsparśa-jā bhogā duḥkha-yonaya eva te", "ādy-antavantaḥ kaunteya na teṣu ramate budhaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Porque los goces nacidos del <a class=\"t\" href=\"glosario.html#sparsa\" data-t=\"sparsa\">contacto</a> son, en verdad, fuentes de dolor; tienen principio y fin, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, y el sabio no se deleita en ellos.</span>", "palabras": [{"iast": "ye", "sa": "ये", "gram": "nom. pl. m. rel.", "es": "los que"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque"}, {"iast": "saṃsparśa-jāḥ", "sa": "संस्पर्शजाः", "gram": "nom. pl. m. comp.", "es": "nacidos del contacto", "ref": "sparsa", "analisis": "sam-sparśa (contacto) + ja (nacido, de √jan)"}, {"iast": "bhogāḥ", "sa": "भोगाः", "gram": "nom. pl. m.", "es": "los goces", "analisis": "√bhuj (disfrutar, comer)"}, {"iast": "duḥkha-yonayaḥ", "sa": "दुःखयोनयः", "gram": "nom. pl. m. comp.", "es": "fuentes de dolor", "analisis": "duḥkha (dolor) + yoni (matriz, origen)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "en verdad"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m.", "es": "ellos"}, {"iast": "ādi-antavantaḥ", "sa": "आद्यन्तवन्तः", "gram": "nom. pl. m. comp.", "es": "que tienen principio y fin", "analisis": "ādi (principio) + anta (fin) + -vat (que tiene)"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh Kaunteya", "ref": "kaunteya"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "teṣu", "sa": "तेषु", "gram": "loc. pl. m.", "es": "en ellos"}, {"iast": "ramate", "sa": "रमते", "gram": "3 sg. pres. med.", "es": "se deleita", "analisis": "√ram (complacerse)"}, {"iast": "budhaḥ", "sa": "बुधः", "gram": "nom. sg. m.", "es": "el sabio", "analisis": "de √budh (despertar, comprender)"}], "nota": "<p><em>Duḥkha-yoni</em>: literalmente «matriz del dolor», aquello de donde el dolor nace. El verso da la razón en la misma frase: «tienen principio y fin»; lo que empieza acaba, y su final se vive como pérdida. <em>Budha</em>, «el que ha despertado, el que entiende», es aquí sinónimo de sabio.</p>", "interp": [{"titulo": "Un eco budista", "html": "<p>La idea de que los placeres nacidos del contacto son fuente de dolor porque son pasajeros está muy cerca de la doctrina budista, para la que lo impermanente es sufrimiento (<em>duḥkha</em>). El capítulo 5 habla además de <em>nirvāṇa</em> (<a class=\"vref\" href=\"capitulo-05.html#v24\" data-v=\"5.24\">5.24</a>–<a class=\"vref\" href=\"capitulo-05.html#v26\" data-v=\"5.26\">5.26</a>), y varios estudiosos, como R. C. Zaehner y K. N. Upadhyaya, ven en él un diálogo con el budismo, aunque otros, como <a class=\"t\" href=\"glosario.html#tilak\" data-t=\"tilak\">Tilak</a>, sostienen que la influencia fue en sentido contrario. En todo caso, la Gītā lo nombra <em>brahma-nirvāṇa</em>, «la extinción en <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>», y lo pone en brahman, una realidad positiva (aunque tampoco el nirvāṇa budista es un mero apagarse).</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "resistir-el-impetu"}, {"n": 23, "hablante": "krsna", "sa": ["शक्नोतीहैव यः सोढुं प्राक्शरीरविमोक्षणात् ।", "कामक्रोधोद्भवं वेगं स युक्तः स सुखी नरः ॥२३॥"], "iast": ["śaknotīhaiva yaḥ soḍhuṃ prāk śarīra-vimokṣaṇāt", "kāma-krodhodbhavaṃ vegaṃ sa yuktaḥ sa sukhī naraḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien es capaz, aquí mismo, antes de verse libre del cuerpo, de resistir el ímpetu que nace del <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a> y de la <a class=\"t\" href=\"glosario.html#krodha\" data-t=\"krodha\">ira</a>, ése está unido en yoga; ése es un hombre feliz.</span>", "palabras": [{"iast": "śaknoti", "sa": "शक्नोति", "gram": "3 sg. pres.", "es": "es capaz", "analisis": "√śak (poder)"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "mismo"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "soḍhum", "sa": "सोढुम्", "gram": "inf.", "es": "de resistir", "analisis": "√sah (soportar, aguantar)"}, {"iast": "prāk", "sa": "प्राक्", "gram": "ind.", "es": "antes de"}, {"iast": "śarīra-vimokṣaṇāt", "sa": "शरीरविमोक्षणात्", "gram": "abl. sg. n. comp.", "es": "de verse libre del cuerpo", "analisis": "śarīra (cuerpo) + vimokṣaṇa (liberación, de vi-√muc «soltar»)"}, {"iast": "kāma-krodha-udbhavam", "sa": "कामक्रोधोद्भवम्", "gram": "ac. sg. m. comp.", "es": "que nace del deseo y de la ira", "analisis": "kāma (deseo) + krodha (ira) + udbhava (origen, de ud-√bhū «surgir»)"}, {"iast": "vegam", "sa": "वेगम्", "gram": "ac. sg. m.", "es": "el ímpetu", "analisis": "de √vij (agitarse)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m.", "es": "ése"}, {"iast": "yuktaḥ", "sa": "युक्तः", "gram": "nom. sg. m. part.", "es": "unido en yoga", "ref": "yoga", "analisis": "√yuj (uncir, unir)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m.", "es": "ése"}, {"iast": "sukhī", "sa": "सुखी", "gram": "nom. sg. m. adj.", "es": "feliz", "analisis": "sukhin, de sukha (dicha)"}, {"iast": "naraḥ", "sa": "नरः", "gram": "nom. sg. m.", "es": "hombre"}], "nota": "<p><em>Prāk śarīra-vimokṣaṇāt</em>, «antes de liberarse del cuerpo»: antes de morir, es decir, mientras se vive. <em>Vega</em> es el ímpetu, la oleada que empuja a actuar; el verso no pide no sentirla, sino resistirla (<em>soḍhum</em>, «aguantar, soportar»). El deseo y la ira son la pareja que el capítulo 3 llamó «el enemigo» (<a class=\"vref\" href=\"capitulo-03.html#v37\" data-v=\"3.37\">3.37</a>).</p>", "interp": [{"titulo": "Hasta el último aliento", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende «antes de liberarse del cuerpo» como «hasta la muerte»: el texto pone ese límite porque, mientras se vive, el ímpetu del deseo y de la ira es inevitable —tiene causas sin número—, y hasta la muerte no hay que confiarse. Describe también sus señales en el cuerpo: el deseo eriza el vello y alegra los ojos y el rostro; la ira hace temblar y sudar, morder los labios y enrojecer los ojos.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Del enemigo a la oleada", "html": "<p>En el capítulo 3 el deseo y la ira eran el enemigo al que había que matar (<a class=\"vref\" href=\"capitulo-03.html#v37\" data-v=\"3.37\">3.37</a>, <a class=\"vref\" href=\"capitulo-03.html#v43\" data-v=\"3.43\">3.43</a>); aquí la consigna es más modesta y más práctica: resistir su ímpetu cuando llega. El final une dos palabras: el que lo logra es <em>yukta</em>, «unido en yoga», y <em>sukhī</em>, «feliz»; el disciplinado y el feliz son el mismo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "resistir-el-impetu"}, {"n": 24, "hablante": "krsna", "sa": ["योऽन्तःसुखोऽन्तरारामस्तथान्तर्ज्योतिरेव यः ।", "स योगी ब्रह्मनिर्वाणं ब्रह्मभूतोऽधिगच्छति ॥२४॥"], "iast": ["yo 'ntaḥ-sukho 'ntar-ārāmas tathāntar-jyotir eva yaḥ", "sa yogī brahma-nirvāṇaṃ brahma-bhūto 'dhigacchati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien halla la dicha en su interior, quien en su interior se deleita y tiene dentro su luz, ese yogui, convertido en <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, alcanza la <a class=\"t\" href=\"glosario.html#nirvana\" data-t=\"nirvana\">extinción en brahman</a>.</span>", "palabras": [{"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron. rel.", "es": "quien"}, {"iast": "antaḥ-sukhaḥ", "sa": "अन्तःसुखः", "gram": "nom. sg. m. comp.", "es": "cuya dicha está dentro", "analisis": "antar (dentro) + sukha (dicha, felicidad)"}, {"iast": "antar-ārāmaḥ", "sa": "अन्तरारामः", "gram": "nom. sg. m. comp.", "es": "cuyo deleite está dentro", "analisis": "antar (dentro) + ārāma (deleite), de ā-√ram (deleitarse)"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así también"}, {"iast": "antar-jyotiḥ", "sa": "अन्तर्ज्योतिः", "gram": "nom. sg. m. comp.", "es": "cuya luz está dentro", "analisis": "antar (dentro) + jyotis (luz)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron. rel.", "es": "quien"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ese"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "el yogui", "ref": "yoga"}, {"iast": "brahma-nirvāṇam", "sa": "ब्रह्मनिर्वाणम्", "gram": "ac. sg. n. comp.", "es": "la extinción en brahman", "ref": "nirvana", "analisis": "brahma (brahman) + nirvāṇa (extinción, apagamiento), de nir-√vā (apagarse soplando)"}, {"iast": "brahma-bhūtaḥ", "sa": "ब्रह्मभूतः", "gram": "nom. sg. m. comp.", "es": "convertido en brahman", "ref": "brahman", "analisis": "brahma (brahman) + bhūta (llegado a ser), ppp de √bhū (ser, llegar a ser)"}, {"iast": "adhigacchati", "sa": "अधिगच्छति", "gram": "3 sg. pres. act.", "es": "alcanza", "analisis": "adhi-√gam (llegar a, alcanzar)"}], "nota": "<p><em>Antaḥ-sukha</em>, <em>antar-ārāma</em>, <em>antar-jyotis</em>: tres compuestos paralelos, «cuya dicha, cuyo deleite, cuya luz están dentro». Responden al verso anterior: la dicha que no viene de los objetos. <em>Brahma-bhūta</em>: «el que ha llegado a ser brahman». <em>Brahma-nirvāṇa</em>: «la extinción en brahman», expresión que ya cerraba el capítulo 2 (<a class=\"vref\" href=\"capitulo-02.html#v72\" data-v=\"2.72\">2.72</a>) y que se repite en los dos versos siguientes; véase la ficha <a class=\"t\" href=\"glosario.html#nirvana\" data-t=\"nirvana\">nirvāṇa</a>.</p>", "interp": [{"titulo": "Brahman ya en esta vida", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende <em>brahma-bhūta</em> como el que, ya en vida, ha llegado a ser brahman, y la extinción en brahman como la liberación misma: no un lugar al que se va después de morir, sino el estado de quien conoce.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La dicha del sí-mismo", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende aquí brahman como el sí-mismo en su pureza, libre de la naturaleza material: el yogui que encuentra dentro su dicha llega a la dicha de experimentar el sí-mismo (<em>ātmānubhava</em>). En el plan de su comentario, esa visión del sí-mismo, meta de los seis primeros capítulos, es el paso previo a la devoción por el Señor, que la Gītā enseña desde el capítulo 7.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Una palabra budista", "html": "<p><em>Nirvāṇa</em> es el término central del budismo para la liberación, y la Gītā lo usa aquí tres veces seguidas. Pero lo califica: no es una extinción sin más, sino la extinción «en brahman», en una realidad positiva, y quien la alcanza es «el que se ha convertido en brahman». Varios estudiosos, como R. C. Zaehner, ven en esta fórmula un diálogo, quizá una respuesta, con el vocabulario budista; Zaehner observa que el compuesto <em>brahma-nirvāṇa</em> parece nacer con la Gītā, y que también <em>brahma-bhūta</em>, «convertido en brahman», tiene paralelo budista.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-extincion-en-brahman"}, {"n": 25, "hablante": "krsna", "sa": ["लभन्ते ब्रह्मनिर्वाणमृषयः क्षीणकल्मषाः ।", "छिन्नद्वैधा यतात्मानः सर्वभूतहिते रताः ॥२५॥"], "iast": ["labhante brahma-nirvāṇam ṛṣayaḥ kṣīṇa-kalmaṣāḥ", "chinna-dvaidhā yatātmānaḥ sarva-bhūta-hite ratāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Alcanzan la <a class=\"t\" href=\"glosario.html#nirvana\" data-t=\"nirvana\">extinción en brahman</a> los <a class=\"t\" href=\"glosario.html#rsi\" data-t=\"rsi\">videntes</a> cuyas impurezas se han agotado, que han cortado la <a class=\"t\" href=\"glosario.html#samsaya\" data-t=\"samsaya\">duda</a>, dueños de sí y entregados al bien de todos los seres.</span>", "palabras": [{"iast": "labhante", "sa": "लभन्ते", "gram": "3 pl. pres. med.", "es": "alcanzan", "analisis": "√labh (obtener)"}, {"iast": "brahma-nirvāṇam", "sa": "ब्रह्मनिर्वाणम्", "gram": "ac. sg. n. comp.", "es": "la extinción en brahman", "ref": "nirvana", "analisis": "brahma (brahman) + nirvāṇa (extinción, apagamiento), de nir-√vā (apagarse soplando)"}, {"iast": "ṛṣayaḥ", "sa": "ऋषयः", "gram": "nom. pl. m.", "es": "los videntes", "ref": "rsi"}, {"iast": "kṣīṇa-kalmaṣāḥ", "sa": "क्षीणकल्मषाः", "gram": "nom. pl. m. comp.", "es": "cuyas impurezas se han agotado", "analisis": "kṣīṇa (agotado, consumido), ppp de √kṣi + kalmaṣa (mancha, impureza)"}, {"iast": "chinna-dvaidhāḥ", "sa": "छिन्नद्वैधाः", "gram": "nom. pl. m. comp.", "es": "que han cortado la duda", "ref": "samsaya", "analisis": "chinna (cortado), ppp de √chid + dvaidha (lo doble: dualidad, duda), de dvi (dos)"}, {"iast": "yata-ātmānaḥ", "sa": "यतात्मानः", "gram": "nom. pl. m. comp.", "es": "dueños de sí", "ref": "atman", "analisis": "yata (dominado), ppp de √yam + ātman (uno mismo)"}, {"iast": "sarva-bhūta-hite", "sa": "सर्वभूतहिते", "gram": "loc. sg. n. comp.", "es": "en el bien de todos los seres", "analisis": "sarva (todo) + bhūta (ser) + hita (bien, provecho)"}, {"iast": "ratāḥ", "sa": "रताः", "gram": "nom. pl. m. ppp", "es": "entregados, que se complacen", "analisis": "√ram (complacerse)"}], "nota": "<p><em>Kalmaṣa</em>: «mancha, impureza», como en <a class=\"vref\" href=\"capitulo-04.html#v30\" data-v=\"4.30\">4.30</a>. <em>Chinna-dvaidha</em>: literalmente «que ha cortado lo doble»; <em>dvaidha</em> es la duplicidad, y de ahí la duda, que divide la mente en dos. Recoge la imagen de <a class=\"vref\" href=\"capitulo-04.html#v42\" data-v=\"4.42\">4.42</a>, la duda cortada con la espada del conocimiento. <em>Yatātman</em>: «de sí mismo dominado».</p>", "interp": [{"titulo": "La extinción y el bien de todos", "html": "<p>La última expresión, <em>sarva-bhūta-hite ratāḥ</em>, «entregados al bien de todos los seres», reaparece idéntica en <a class=\"vref\" href=\"capitulo-12.html#v4\" data-v=\"12.4\">12.4</a>. El retrato es significativo: los que alcanzan la extinción en brahman se ocupan del bien de todos. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo entiende de otro modo: estos videntes son renunciantes, y su entrega al bien de todos consiste en no dañar a ningún ser (<em>ahiṃsaka</em>). La Gītā une así la meta más alta con el <a class=\"t\" href=\"glosario.html#lokasangraha\" data-t=\"lokasangraha\">bien del mundo</a> de <a class=\"vref\" href=\"capitulo-03.html#v20\" data-v=\"3.20\">3.20</a>–<a class=\"vref\" href=\"capitulo-03.html#v25\" data-v=\"3.25\">3.25</a>.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-extincion-en-brahman"}, {"n": 26, "hablante": "krsna", "sa": ["कामक्रोधवियुक्तानां यतीनां यतचेतसाम् ।", "अभितो ब्रह्मनिर्वाणं वर्तते विदितात्मनाम् ॥२६॥"], "iast": ["kāma-krodha-viyuktānāṃ yatīnāṃ yata-cetasām", "abhito brahma-nirvāṇaṃ vartate viditātmanām"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">A los <a class=\"t\" href=\"glosario.html#yati\" data-t=\"yati\">ascetas</a> libres de <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a> y de <a class=\"t\" href=\"glosario.html#krodha\" data-t=\"krodha\">ira</a>, de pensamiento dominado, que conocen el sí-mismo, la <a class=\"t\" href=\"glosario.html#nirvana\" data-t=\"nirvana\">extinción en brahman</a> los rodea por todas partes.</span>", "palabras": [{"iast": "kāma-krodha-viyuktānām", "sa": "कामक्रोधवियुक्तानाम्", "gram": "gen. pl. m. comp.", "es": "de los libres de deseo e ira", "ref": "kama", "analisis": "kāma (deseo) + krodha (ira) + viyukta (separado, libre), ppp de vi-√yuj"}, {"iast": "yatīnām", "sa": "यतीनाम्", "gram": "gen. pl. m.", "es": "de los ascetas", "ref": "yati"}, {"iast": "yata-cetasām", "sa": "यतचेतसाम्", "gram": "gen. pl. m. comp.", "es": "de pensamiento dominado", "analisis": "yata (dominado), ppp de √yam + cetas (pensamiento, mente)"}, {"iast": "abhitaḥ", "sa": "अभितः", "gram": "ind.", "es": "alrededor, por ambos lados; cerca"}, {"iast": "brahma-nirvāṇam", "sa": "ब्रह्मनिर्वाणम्", "gram": "ac. sg. n. comp.", "es": "la extinción en brahman", "ref": "nirvana", "analisis": "brahma (brahman) + nirvāṇa (extinción, apagamiento), de nir-√vā (apagarse soplando)"}, {"iast": "vartate", "sa": "वर्तते", "gram": "3 sg. pres. med.", "es": "está, se halla", "analisis": "√vṛt (estar, encontrarse)"}, {"iast": "vidita-ātmanām", "sa": "विदितात्मनाम्", "gram": "gen. pl. m. comp.", "es": "de los que conocen el sí-mismo", "ref": "atman", "analisis": "vidita (conocido), ppp de √vid + ātman (el sí-mismo)"}], "nota": "<p><em>Yati</em>: «asceta», el que se esfuerza en la disciplina (véase <a class=\"vref\" href=\"capitulo-04.html#v28\" data-v=\"4.28\">4.28</a>); el verso juega con el sonido de <em>yatīnāṃ yata-cetasām</em>. <em>Abhitaḥ</em> significa «alrededor, por ambos lados» y también «cerca»; de ahí las alternativas. <em>Viditātman</em>: «el que conoce el sí-mismo».</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Los ascetas libres de deseo y de ira, de pensamiento dominado, que conocen el sí-mismo, gozan de la extinción en brahman en esta vida y después de ella.", "nota": "<p>Con <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, que glosa <em>abhitaḥ</em> como «por ambos lados»: para los que están vivos y para los que han muerto. La liberación no espera a la muerte.</p>"}, {"html": "Los ascetas libres de deseo y de ira, de pensamiento dominado, que conocen el sí-mismo, tienen cerca la extinción en brahman.", "nota": "<p>Con <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, que toma <em>abhitaḥ</em> en su otro sentido, «cerca, al alcance»: para ellos la extinción en brahman está «en la mano» (<em>hasta-stha</em>); no es una meta lejana.</p>"}], "ens": "la-extincion-en-brahman"}, {"n": 27, "hablante": "krsna", "sa": ["स्पर्शान्कृत्वा बहिर्बाह्यांश्चक्षुश्चैवान्तरे भ्रुवोः ।", "प्राणापानौ समौ कृत्वा नासाभ्यन्तरचारिणौ ॥२७॥"], "iast": ["sparśān kṛtvā bahir bāhyāṃś cakṣuś caivāntare bhruvoḥ", "prāṇāpānau samau kṛtvā nāsābhyantara-cāriṇau"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Dejando fuera los <a class=\"t\" href=\"glosario.html#sparsa\" data-t=\"sparsa\">contactos</a> externos, con la mirada entre las cejas, igualando el <a class=\"t\" href=\"glosario.html#prana\" data-t=\"prana\">prāṇa</a> y el <a class=\"t\" href=\"glosario.html#apana\" data-t=\"apana\">apāna</a> que circulan por dentro de la nariz,</span>", "palabras": [{"iast": "sparśān", "sa": "स्पर्शान्", "gram": "ac. pl. m.", "es": "los contactos", "ref": "sparsa", "analisis": "√spṛś (tocar)"}, {"iast": "kṛtvā", "sa": "कृत्वा", "gram": "abs.", "es": "poniendo, dejando", "analisis": "√kṛ (hacer)"}, {"iast": "bahiḥ", "sa": "बहिः", "gram": "ind.", "es": "fuera"}, {"iast": "bāhyān", "sa": "बाह्यान्", "gram": "ac. pl. m.", "es": "externos"}, {"iast": "cakṣuḥ", "sa": "चक्षुः", "gram": "ac. sg. n.", "es": "la mirada, el ojo"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "antare", "sa": "अन्तरे", "gram": "loc. sg. n.", "es": "en medio, entre"}, {"iast": "bhruvoḥ", "sa": "भ्रुवोः", "gram": "gen. du. f.", "es": "de las cejas", "analisis": "bhrū (ceja)"}, {"iast": "prāṇa-apānau", "sa": "प्राणापानौ", "gram": "ac. du. m. comp.", "es": "el prāṇa y el apāna", "ref": "prana", "analisis": "prāṇa + apāna: los dos alientos principales"}, {"iast": "samau", "sa": "समौ", "gram": "ac. du. m.", "es": "iguales", "ref": "samatva"}, {"iast": "kṛtvā", "sa": "कृत्वा", "gram": "abs.", "es": "haciendo"}, {"iast": "nāsā-abhyantara-cāriṇau", "sa": "नासाभ्यन्तरचारिणौ", "gram": "ac. du. m. comp.", "es": "que circulan por dentro de la nariz", "analisis": "nāsā (nariz) + abhyantara (interior) + cārin (que se mueve), de √car (moverse)"}], "nota": "<p><em>Sparśa</em>: «contacto», el encuentro de los sentidos con sus objetos (<a class=\"vref\" href=\"capitulo-02.html#v14\" data-v=\"2.14\">2.14</a>; <a class=\"vref\" href=\"capitulo-05.html#v21\" data-v=\"5.21\">5.21</a>–<a class=\"vref\" href=\"capitulo-05.html#v22\" data-v=\"5.22\">5.22</a>); «dejarlos fuera» es no dejarlos entrar en la mente. <em>Antare bhruvoḥ</em>: «entre las cejas». <em>Prāṇa</em> y <em>apāna</em> quedan sin traducir, como en <a class=\"vref\" href=\"capitulo-04.html#v29\" data-v=\"4.29\">4.29</a>, porque los textos no coinciden en cuál es la inspiración (véanse las alternativas y la ficha <a class=\"t\" href=\"glosario.html#prana\" data-t=\"prana\">prāṇa</a>); <em>samau kṛtvā</em>, «haciéndolos iguales», suele entenderse como dar a los dos movimientos del aliento el mismo ritmo, lento y regular; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, en cambio, lo entienden como suspenderlos (<em>kumbhaka</em>), y Śrīdhara admite también un aliento tan lento que ni sale de la nariz ni entra más allá de ella. La frase continúa en el verso siguiente.</p>", "interp": [{"titulo": "El esbozo de la meditación", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> presenta 5.27–5.28 como el enunciado breve, a modo de <em>sūtra</em>, del yoga de la meditación (<em>dhyāna-yoga</em>), el medio más inmediato del conocimiento recto, que el capítulo siguiente expondrá por extenso.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Dónde se fija la mirada", "html": "<p>En <a class=\"vref\" href=\"capitulo-06.html#v13\" data-v=\"6.13\">6.13</a>, al describir la postura de meditación, la mirada se fija en la punta de la nariz; en <a class=\"vref\" href=\"capitulo-08.html#v10\" data-v=\"8.10\">8.10</a>, a la hora de la muerte, el yogui lleva el aliento vital al entrecejo. Los dos versos de aquí son un primer esbozo de la técnica que el capítulo 6 desarrollará.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Miembros del yoga", "html": "<p>En pocas palabras, el verso reúne prácticas que el yoga clásico separará en miembros distintos: dejar fuera los contactos externos anticipa lo que los <em>Yoga-sūtra</em> llamarán <em>pratyāhāra</em>, la retirada de los sentidos (2.54), e igualar los alientos, el <a class=\"t\" href=\"glosario.html#pranayama\" data-t=\"pranayama\">control del aliento</a> (2.49).</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Dejando fuera los contactos externos, con la mirada entre las cejas, igualando el aire que sale y el que entra por dentro de la nariz,", "nota": "<p>Con la correspondencia que <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> dan en <a class=\"vref\" href=\"capitulo-04.html#v29\" data-v=\"4.29\">4.29</a>: el <em>prāṇa</em> es el aire que sale, y el <em>apāna</em>, el que entra.</p>"}, {"html": "Dejando fuera los contactos externos, con la mirada entre las cejas, igualando la inspiración y la espiración que circulan por dentro de la nariz,", "nota": "<p>Con la correspondencia frecuente en el yoga moderno: el <em>prāṇa</em> es el aire que entra, y el <em>apāna</em>, el que sale. Aquí la diferencia importa menos que en 4.29, porque lo que pide el verso es igualar los dos movimientos.</p>"}], "ens": "meditar-con-la-mirada-entre-las-cejas"}, {"n": 28, "hablante": "krsna", "sa": ["यतेन्द्रियमनोबुद्धिर्मुनिर्मोक्षपरायणः ।", "विगतेच्छाभयक्रोधो यः सदा मुक्त एव सः ॥२८॥"], "iast": ["yatendriya-mano-buddhir munir mokṣa-parāyaṇaḥ", "vigatecchā-bhaya-krodho yaḥ sadā mukta eva saḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">con los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a>, la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> y el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> dominados, el <a class=\"t\" href=\"glosario.html#muni\" data-t=\"muni\">sabio</a> que tiene por meta la <a class=\"t\" href=\"glosario.html#moksa\" data-t=\"moksa\">liberación</a>, libre de anhelo, de miedo y de ira: quien es así está liberado ya, para siempre.</span>", "palabras": [{"iast": "yata-indriya-manaḥ-buddhiḥ", "sa": "यतेन्द्रियमनोबुद्धिः", "gram": "nom. sg. m. comp.", "es": "con los sentidos, la mente y el entendimiento dominados", "ref": "indriya", "analisis": "yata (dominado), ppp de √yam + indriya (sentido) + manas (mente) + buddhi (entendimiento)"}, {"iast": "muniḥ", "sa": "मुनिः", "gram": "nom. sg. m.", "es": "el sabio", "ref": "muni"}, {"iast": "mokṣa-parāyaṇaḥ", "sa": "मोक्षपरायणः", "gram": "nom. sg. m. comp.", "es": "que tiene por meta suprema la liberación", "ref": "moksa", "analisis": "mokṣa (liberación) + parāyaṇa (meta suprema, entregado a)"}, {"iast": "vigata-icchā-bhaya-krodhaḥ", "sa": "विगतेच्छाभयक्रोधः", "gram": "nom. sg. m. comp.", "es": "libre de anhelo, miedo e ira", "ref": "krodha", "analisis": "vigata (ido, desaparecido), ppp de vi-√gam + icchā (anhelo) + bhaya (miedo) + krodha (ira)"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron. rel.", "es": "quien"}, {"iast": "sadā", "sa": "सदा", "gram": "ind.", "es": "siempre"}, {"iast": "muktaḥ", "sa": "मुक्तः", "gram": "nom. sg. m. ppp", "es": "liberado", "ref": "moksa", "analisis": "√muc (soltar, liberar)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente, ya"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ese"}], "nota": "<p><em>Mokṣa-parāyaṇa</em>: «que tiene la liberación como meta suprema». <em>Icchā</em>: «anhelo», cercano a <em>kāma</em>. La tríada «anhelo, miedo e ira» recuerda la del sabio de sabiduría firme, «libre de pasión, miedo e ira» (<a class=\"vref\" href=\"capitulo-02.html#v56\" data-v=\"2.56\">2.56</a>), y la de <a class=\"vref\" href=\"capitulo-04.html#v10\" data-v=\"4.10\">4.10</a>. <em>Sadā mukta eva</em>: «está ya liberado, siempre»: la liberación no espera a la muerte. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lo entiende así: está liberado ya mientras practica, aunque la plena dicha del sí-mismo llegue al caer el cuerpo.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "meditar-con-la-mirada-entre-las-cejas"}, {"n": 29, "hablante": "krsna", "sa": ["भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम् ।", "सुहृदं सर्वभूतानां ज्ञात्वा मां शान्तिमृच्छति ॥२९॥"], "iast": ["bhoktāraṃ yajña-tapasāṃ sarva-loka-maheśvaram", "suhṛdaṃ sarva-bhūtānāṃ jñātvā māṃ śāntim ṛcchati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien me conoce como el que disfruta de los <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificios</a> y las <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridades</a>, el <a class=\"t\" href=\"glosario.html#mahesvara\" data-t=\"mahesvara\">gran Señor</a> de todos los mundos, el amigo de todos los seres, alcanza la <a class=\"t\" href=\"glosario.html#santi\" data-t=\"santi\">paz</a>.</span>", "palabras": [{"iast": "bhoktāram", "sa": "भोक्तारम्", "gram": "ac. sg. m.", "es": "el que disfruta, el que recibe", "analisis": "√bhuj (gozar, comer)"}, {"iast": "yajña-tapasām", "sa": "यज्ञतपसाम्", "gram": "gen. pl. n. comp.", "es": "de los sacrificios y las austeridades", "ref": "yajna", "analisis": "yajña (sacrificio) + tapas (austeridad)"}, {"iast": "sarva-loka-maheśvaram", "sa": "सर्वलोकमहेश्वरम्", "gram": "ac. sg. m. comp.", "es": "el gran Señor de todos los mundos", "ref": "mahesvara", "analisis": "sarva (todo) + loka (mundo) + mahā (grande) + īśvara (señor)"}, {"iast": "suhṛdam", "sa": "सुहृदम्", "gram": "ac. sg. m.", "es": "el amigo", "analisis": "su (bien) + hṛd (corazón): «de buen corazón»"}, {"iast": "sarva-bhūtānām", "sa": "सर्वभूतानाम्", "gram": "gen. pl. n. comp.", "es": "de todos los seres", "analisis": "sarva (todo) + bhūta (ser)"}, {"iast": "jñātvā", "sa": "ज्ञात्वा", "gram": "abs.", "es": "conociendo", "analisis": "√jñā (conocer)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "śāntim", "sa": "शान्तिम्", "gram": "ac. sg. f.", "es": "la paz", "ref": "santi"}, {"iast": "ṛcchati", "sa": "ऋच्छति", "gram": "3 sg. pres. act.", "es": "alcanza", "analisis": "√ṛ (ir, llegar)"}], "nota": "<p><em>Bhoktṛ</em>: «el que goza, el que come»; en el rito, el destinatario que recibe la ofrenda (compárese <a class=\"vref\" href=\"capitulo-09.html#v24\" data-v=\"9.24\">9.24</a>: «yo soy quien disfruta de todos los sacrificios»). <em>Suhṛd</em>: «amigo», literalmente «de buen corazón». El capítulo, que ha hablado de la renuncia, de la acción y de la meditación, termina en el conocimiento de Kṛṣṇa, y en la paz que trae.</p>", "interp": [{"titulo": "Agente y destinatario", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica que el Señor es quien disfruta de los sacrificios y austeridades como su agente y como la divinidad a la que se dirigen, y que es amigo de todos los seres porque les hace bien sin esperar nada a cambio.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Un yoga gozoso", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee el verso en clave del yoga de la acción: quien sabe que el Señor de todos los mundos es también su amigo practica la acción como un culto a él, y la encuentra fácil y gozosa; ésa es la paz que alcanza.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "El amigo", "html": "<p>Para las lecturas devocionales, la palabra decisiva del verso es <em>suhṛd</em>, «amigo». El gran Señor de todos los mundos, el destinatario de todos los sacrificios, es a la vez el amigo de cada ser: la majestad y la cercanía no se excluyen. Es una anticipación de la devoción que la Gītā desarrollará en los capítulos centrales.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-amigo-de-todos-los-seres"}], "ensenanzas": [{"id": "renunciante-que-actua", "desde": 2, "hasta": 3, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El renunciante que sigue actuando", "resumen": "<p>La renuncia y el yoga de la acción llevan al bien supremo, pero el yoga de la acción es superior. El verdadero renunciante no es quien deja de actuar, sino quien ya no odia ni desea: libre de los pares de opuestos, se libera sin esfuerzo de la atadura, aunque siga obrando. La renuncia se traslada de la forma de vida a la actitud (<a class=\"vref\" href=\"capitulo-06.html#v1\" data-v=\"6.1\">6.1</a>).</p>"}, {"id": "sankhya-y-yoga-uno", "desde": 4, "hasta": 6, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Sāṅkhya y yoga son uno", "resumen": "<p>Sólo los ingenuos separan la vía del conocimiento y la de la acción: quien se establece de verdad en una obtiene el fruto de ambas, y quien ve que son una, ése ve. Pero la renuncia es difícil sin yoga; el que se disciplina en la acción llega pronto a brahman.</p>"}, {"id": "no-hago-nada", "desde": 7, "hasta": 9, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "«No hago nada»", "resumen": "<p>Una manera de mirar la propia actividad. El <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a>, con la mente purificada y los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a> dominados, sigue viendo, oyendo, comiendo, andando y respirando; pero mientras lo hace tiene presente que son los sentidos los que se mueven entre sus <a class=\"t\" href=\"glosario.html#visaya\" data-t=\"visaya\">objetos</a>, y piensa: «No hago nada». Así actúa sin mancharse, y su <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a> deja de separarse del de los demás seres.</p>"}, {"id": "hoja-de-loto", "desde": 10, "hasta": 12, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Como la hoja de loto en el agua", "resumen": "<p>Actuar depositando las <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a> en <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> y abandonando el apego: el que lo hace está en el mundo sin que el mundo se le adhiera, como la hoja de loto en el agua. Los yoguis actúan con el cuerpo, la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a>, el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> y los sentidos, pero sin apego, para purificarse. La diferencia entre el libre y el atado no es la acción, sino el apego al <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a>: el <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">disciplinado</a> alcanza la <a class=\"t\" href=\"glosario.html#santi\" data-t=\"santi\">paz</a> definitiva; el que actúa movido por el <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a> queda atado.</p>"}, {"id": "renunciar-con-la-mente", "desde": 13, "hasta": 13, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Renunciar con la mente: vivir en el cuerpo sin creerse su agente", "resumen": "<p>La renuncia que pide la Gītā no consiste en dejar de actuar, sino en renunciar «con la mente» a todas las acciones: quien domina sus sentidos vive en el cuerpo, la ciudad de nueve puertas, sin pensar que es él quien hace o hace hacer. Así se puede actuar y estar, a la vez, en calma.</p>"}, {"id": "quien-actua-es-la-naturaleza", "desde": 14, "hasta": 15, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Quién actúa: la naturaleza propia", "resumen": "<p>Ni el Señor ni el sí-mismo crean la condición de agente, las acciones o su encadenamiento con el fruto: lo que actúa es la naturaleza propia de cada uno (<a class=\"vref\" href=\"capitulo-03.html#v27\" data-v=\"3.27\">3.27</a>). Tampoco el Señor carga con el pecado o el mérito de nadie. Si los hombres piensan otra cosa es porque la ignorancia cubre el conocimiento.</p>"}, {"id": "el-conocimiento-como-el-sol", "desde": 16, "hasta": 17, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El conocimiento que, como el sol, ilumina lo supremo", "resumen": "<p>Cuando el conocimiento destruye la ignorancia, no produce lo supremo: lo deja ver, como el sol muestra las cosas. Quienes vuelven hacia eso el entendimiento, el ser, la vida y la meta quedan limpios de impurezas y salen del ciclo de renacimientos.</p>"}, {"id": "la-misma-mirada", "desde": 18, "hasta": 20, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "La misma mirada", "resumen": "<p>El sabio ve con la misma mirada al <a class=\"t\" href=\"glosario.html#brahmana\" data-t=\"brahmana\">brahmán</a> instruido, a la vaca, al elefante, al perro y al <a class=\"t\" href=\"glosario.html#svapaka\" data-t=\"svapaka\">paria</a> (<a class=\"vref\" href=\"capitulo-05.html#v18\" data-v=\"5.18\">5.18</a>). Esa igualdad (<em>sāmya</em>) no borra las diferencias entre los seres: está en la mirada, que ve en todos lo mismo. Quien se asienta en ella se asienta en <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, que es igual y sin defecto, y ha vencido ya en esta vida el ciclo de los nacimientos (<a class=\"vref\" href=\"capitulo-05.html#v19\" data-v=\"5.19\">5.19</a>). Su señal es la estabilidad: no se exalta con lo agradable ni se turba con lo desagradable (<a class=\"vref\" href=\"capitulo-05.html#v20\" data-v=\"5.20\">5.20</a>).</p>"}, {"id": "resistir-el-impetu", "desde": 21, "hasta": 23, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "La dicha interior y el ímpetu del deseo", "resumen": "<p>Tres pasos: no apegarse a los <a class=\"t\" href=\"glosario.html#sparsa\" data-t=\"sparsa\">contactos</a> de los sentidos con lo externo y hallar la dicha en el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a> (<a class=\"vref\" href=\"capitulo-05.html#v21\" data-v=\"5.21\">5.21</a>); reconocer que los goces nacidos del contacto, porque tienen principio y fin, son fuentes de dolor (<a class=\"vref\" href=\"capitulo-05.html#v22\" data-v=\"5.22\">5.22</a>); y, mientras se vive, resistir el ímpetu del <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a> y de la <a class=\"t\" href=\"glosario.html#krodha\" data-t=\"krodha\">ira</a> cuando llega (<a class=\"vref\" href=\"capitulo-05.html#v23\" data-v=\"5.23\">5.23</a>). Quien lo logra está unido en yoga y es feliz.</p>"}, {"id": "la-extincion-en-brahman", "desde": 24, "hasta": 26, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "La extinción en brahman", "resumen": "<p>Quien encuentra dentro de sí la dicha, el deleite y la luz ya no depende de los objetos: convertido en <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, alcanza la <a class=\"t\" href=\"glosario.html#nirvana\" data-t=\"nirvana\">extinción en brahman</a>. La alcanzan los que han agotado sus impurezas y cortado sus dudas, dueños de sí y entregados al bien de todos los seres; para los ascetas libres de deseo e ira, está ya a su alrededor.</p>"}, {"id": "meditar-con-la-mirada-entre-las-cejas", "desde": 27, "hasta": 28, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Dejar fuera los contactos y aquietar el aliento", "resumen": "<p>Un primer esbozo de la meditación: dejar fuera los <a class=\"t\" href=\"glosario.html#sparsa\" data-t=\"sparsa\">contactos</a> externos, fijar la mirada entre las cejas, igualar los dos movimientos del aliento (<a class=\"t\" href=\"glosario.html#prana\" data-t=\"prana\">prāṇa</a> y apāna) que circulan por la nariz, y dominar los sentidos, la mente y el entendimiento. Quien lo hace con la liberación como meta, libre de anhelo, miedo e ira, está liberado ya. El capítulo 6 desarrollará la técnica.</p>"}, {"id": "el-amigo-de-todos-los-seres", "desde": 29, "hasta": 29, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Conocer al amigo de todos los seres", "resumen": "<p>La paz llega al conocer a Kṛṣṇa en tres facetas: el que recibe todos los <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificios</a> y <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridades</a>, el <a class=\"t\" href=\"glosario.html#mahesvara\" data-t=\"mahesvara\">gran Señor</a> de todos los mundos y el amigo de todos los seres.</p>"}]};
